DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.admin_apply_fix_proposal(p_id uuid, p_confirm boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_prop public.holdings_fix_proposals;
  v_result jsonb := '{}'::jsonb;
  v_ids uuid[];
BEGIN
  IF NOT public.has_role(v_uid, 'company_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_confirm IS NOT TRUE THEN
    RAISE EXCEPTION 'confirmation required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_prop FROM public.holdings_fix_proposals WHERE id = p_id FOR UPDATE;
  IF v_prop.id IS NULL THEN
    RAISE EXCEPTION 'proposal not found';
  END IF;
  IF v_prop.status <> 'pending' THEN
    RAISE EXCEPTION 'proposal is not pending (status=%)', v_prop.status;
  END IF;

  BEGIN
    IF v_prop.proposed_action = 'normalize_unit' THEN
      SELECT ARRAY(SELECT jsonb_array_elements_text(v_prop.payload->'signal_ids'))::uuid[] INTO v_ids;
      UPDATE public.expert_signals
         SET quantity_unit = v_prop.payload->>'target_unit'
       WHERE id = ANY(v_ids);
      v_result := jsonb_build_object('updated_signals', array_length(v_ids,1));

    ELSIF v_prop.proposed_action = 'adjust_trade_quantity' THEN
      UPDATE public.trade_records
         SET quantity = (v_prop.payload->>'to_quantity')::numeric
       WHERE id = (v_prop.payload->>'trade_id')::uuid;
      v_result := jsonb_build_object('updated_trade_id', v_prop.payload->>'trade_id');

    ELSIF v_prop.proposed_action = 'close_trade_record' THEN
      UPDATE public.trade_records
         SET status = 'closed', exit_date = COALESCE(exit_date, now())
       WHERE id = (v_prop.payload->>'trade_id')::uuid;
      v_result := jsonb_build_object('closed_trade_id', v_prop.payload->>'trade_id');

    ELSIF v_prop.proposed_action = 'cancel_signal' THEN
      DELETE FROM public.expert_signals
       WHERE id = (v_prop.payload->>'signal_id')::uuid
         AND status = 'pending';
      v_result := jsonb_build_object('deleted_signal_id', v_prop.payload->>'signal_id');

    ELSIF v_prop.proposed_action = 'manual_review' THEN
      RAISE EXCEPTION 'this proposal requires manual handling and cannot be auto-applied';
    ELSE
      RAISE EXCEPTION 'unsupported proposed_action %', v_prop.proposed_action;
    END IF;

    UPDATE public.holdings_fix_proposals
       SET status = 'applied',
           applied_by = v_uid,
           applied_at = now(),
           apply_result = v_result
     WHERE id = p_id;

    INSERT INTO public.audit_logs(actor_id, action, target_type, target_id, detail)
    VALUES (v_uid, 'fix_proposal.apply', 'holdings_fix_proposals', p_id,
            jsonb_build_object('action', v_prop.proposed_action, 'payload', v_prop.payload, 'result', v_result));

  EXCEPTION WHEN OTHERS THEN
    UPDATE public.holdings_fix_proposals
       SET status = 'failed',
           applied_by = v_uid,
           applied_at = now(),
           apply_result = jsonb_build_object('error', SQLERRM)
     WHERE id = p_id;
    RAISE;
  END;

  RETURN v_result;
END $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.admin_checkup_usage_overview()
 RETURNS TABLE(user_id uuid, display_name text, email text, tier text, period text, used integer, quota_limit integer, remaining integer, usage_pct numeric, resets_at timestamp with time zone, is_near_limit boolean, is_exhausted boolean, last_used_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden: company_admin role required';
  END IF;

  RETURN QUERY
  WITH all_users AS (
    SELECT DISTINCT cu.user_id
    FROM public.checkup_usage cu
    WHERE cu.used_at >= (date_trunc('month', (now() AT TIME ZONE 'Asia/Taipei')) AT TIME ZONE 'Asia/Taipei')
    UNION
    SELECT cs.user_id
    FROM public.checkup_subscriptions cs
    WHERE cs.status = 'active' AND (cs.expires_at IS NULL OR cs.expires_at > now())
  ),
  enriched AS (
    SELECT
      u.user_id,
      public.check_checkup_quota(u.user_id) AS q
    FROM all_users u
  )
  SELECT
    e.user_id,
    p.display_name,
    au.email::text,
    (e.q->>'tier')::text,
    (e.q->>'period')::text,
    (e.q->>'used')::int,
    (e.q->>'limit')::int,
    (e.q->>'remaining')::int,
    CASE WHEN (e.q->>'limit')::int > 0
      THEN ROUND(((e.q->>'used')::numeric / (e.q->>'limit')::numeric) * 100, 1)
      ELSE 0 END,
    (e.q->>'resets_at')::timestamptz,
    CASE WHEN (e.q->>'limit')::int > 0
      THEN ((e.q->>'used')::numeric / (e.q->>'limit')::numeric) >= 0.8
      ELSE false END,
    ((e.q->>'remaining')::int <= 0),
    (SELECT MAX(used_at) FROM public.checkup_usage WHERE checkup_usage.user_id = e.user_id)
  FROM enriched e
  LEFT JOIN public.profiles p ON p.user_id = e.user_id
  LEFT JOIN auth.users au ON au.id = e.user_id
  ORDER BY
    ((e.q->>'remaining')::int) ASC,
    CASE WHEN (e.q->>'limit')::int > 0
      THEN ((e.q->>'used')::numeric / (e.q->>'limit')::numeric)
      ELSE 0 END DESC;
END;
$function$
