DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.admin_reset_line_free_quota(_line_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_user_id uuid;
  v_before jsonb;
  v_after jsonb;
  v_deleted int := 0;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF NOT public.has_role(v_caller, 'company_admin'::app_role) THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;
  IF _line_user_id IS NULL OR length(trim(_line_user_id)) = 0 THEN
    RAISE EXCEPTION 'MISSING_LINE_USER_ID';
  END IF;

  SELECT user_id INTO v_user_id
    FROM public.profiles
   WHERE line_user_id = _line_user_id
   LIMIT 1;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'LINE_USER_NOT_FOUND';
  END IF;

  v_before := public.check_checkup_quota(v_user_id);

  WITH del AS (
    DELETE FROM public.checkup_usage
     WHERE user_id = v_user_id
       AND kind = 'daily-analysis'
     RETURNING 1
  )
  SELECT count(*)::int INTO v_deleted FROM del;

  v_after := public.check_checkup_quota(v_user_id);

  INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, detail)
  VALUES (
    v_caller,
    'checkup_quota.admin_reset_line_free',
    'profile',
    v_user_id,
    jsonb_build_object(
      'line_user_id', _line_user_id,
      'deleted_count', v_deleted,
      'before', v_before,
      'after', v_after,
      'at', now()
    )
  );

  RETURN jsonb_build_object(
    'user_id', v_user_id,
    'line_user_id', _line_user_id,
    'deleted_count', v_deleted,
    'before', v_before,
    'after', v_after
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.admin_signal_dupe_trades_audit()
 RETURNS TABLE(signal_id uuid, expert_id uuid, expert_name text, instrument text, action text, signal_published_at timestamp with time zone, dup_count integer, open_count integer, trade_ids uuid[], has_manual_edit boolean, earliest_created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH grp AS (
    SELECT
      t.signal_id,
      COUNT(*)::int AS c,
      COUNT(*) FILTER (WHERE t.exit_date IS NULL)::int AS oc,
      array_agg(t.id ORDER BY t.created_at ASC, t.id ASC) AS ids,
      MIN(t.created_at) AS mn,
      -- 疑似人工編輯：任一筆已有 exit_date、或不同筆 entry_price/quantity/quantity_unit/entry_date 不一致
      (
        BOOL_OR(t.exit_date IS NOT NULL)
        OR COUNT(DISTINCT t.entry_price) > 1
        OR COUNT(DISTINCT t.quantity) > 1
        OR COUNT(DISTINCT t.quantity_unit) > 1
        OR COUNT(DISTINCT t.entry_date) > 1
      ) AS manual
    FROM public.trade_records t
    WHERE t.signal_id IS NOT NULL
    GROUP BY t.signal_id
    HAVING COUNT(*) > 1
  )
  SELECT
    g.signal_id,
    s.expert_id,
    e.name,
    COALESCE(s.instrument, ''),
    s.action::text,
    s.published_at,
    g.c,
    g.oc,
    g.ids,
    g.manual,
    g.mn
  FROM grp g
  LEFT JOIN public.expert_signals s ON s.id = g.signal_id
  LEFT JOIN public.experts e ON e.id = s.expert_id
  ORDER BY g.mn DESC NULLS LAST;
END; $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.admin_signal_dupe_trades_fix(p_signal_id uuid, p_dry_run boolean DEFAULT true, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_keep uuid;
  v_remove uuid[];
  v_manual boolean;
  v_actor uuid := auth.uid();
BEGIN
  IF NOT has_role(v_actor, 'company_admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_keep
  FROM public.trade_records
  WHERE signal_id = p_signal_id
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_keep IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'note', 'no_rows', 'kept_id', null, 'removed_ids', '[]'::jsonb, 'executed', false);
  END IF;

  SELECT array_agg(id ORDER BY created_at ASC, id ASC) INTO v_remove
  FROM public.trade_records
  WHERE signal_id = p_signal_id AND id <> v_keep;

  IF v_remove IS NULL OR array_length(v_remove, 1) IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'note', 'no_dupes', 'kept_id', v_keep, 'removed_ids', '[]'::jsonb, 'executed', false);
  END IF;

  SELECT (
    BOOL_OR(exit_date IS NOT NULL)
    OR COUNT(DISTINCT entry_price) > 1
    OR COUNT(DISTINCT quantity) > 1
    OR COUNT(DISTINCT quantity_unit) > 1
    OR COUNT(DISTINCT entry_date) > 1
  )
  INTO v_manual
  FROM public.trade_records
  WHERE signal_id = p_signal_id;

  IF p_dry_run THEN
    RETURN jsonb_build_object(
      'ok', true, 'kept_id', v_keep, 'removed_ids', to_jsonb(v_remove),
      'would_remove_count', array_length(v_remove, 1),
      'has_manual_edit', v_manual, 'executed', false
    );
  END IF;

  IF v_manual AND NOT p_force THEN
    RAISE EXCEPTION 'manual_edit_detected_require_force' USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM public.trade_records WHERE id = ANY(v_remove);

  INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, detail)
  VALUES (
    v_actor, 'signal_dupe_trade_fix', 'signal', p_signal_id,
    jsonb_build_object(
      'kept_id', v_keep,
      'removed_ids', to_jsonb(v_remove),
      'removed_count', array_length(v_remove, 1),
      'has_manual_edit', v_manual,
      'forced', p_force
    )
  );

  RETURN jsonb_build_object(
    'ok', true, 'kept_id', v_keep, 'removed_ids', to_jsonb(v_remove),
    'removed_count', array_length(v_remove, 1),
    'has_manual_edit', v_manual, 'executed', true
  );
END; $function$
