DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_via text;
  v_target uuid;
  v_before jsonb;
  v_after jsonb;
  v_changed text[];
  v_expert uuid;
BEGIN
  BEGIN
    v_actor := auth.uid();
  EXCEPTION WHEN OTHERS THEN v_actor := NULL;
  END;

  BEGIN
    v_via := auth.role();
  EXCEPTION WHEN OTHERS THEN v_via := NULL;
  END;

  IF TG_OP = 'DELETE' THEN
    v_before := to_jsonb(OLD);
    v_target := (v_before->>'id')::uuid;
    v_expert := NULLIF(v_before->>'expert_id','')::uuid;
  ELSIF TG_OP = 'INSERT' THEN
    v_after := to_jsonb(NEW);
    v_target := (v_after->>'id')::uuid;
    v_expert := NULLIF(v_after->>'expert_id','')::uuid;
  ELSE  -- UPDATE
    v_before := to_jsonb(OLD);
    v_after := to_jsonb(NEW);
    v_target := (v_after->>'id')::uuid;
    v_expert := NULLIF(v_after->>'expert_id','')::uuid;
    SELECT COALESCE(array_agg(k ORDER BY k), ARRAY[]::text[])
      INTO v_changed
    FROM (
      SELECT key AS k
      FROM jsonb_each(v_after) a
      WHERE key NOT IN ('updated_at')
        AND (v_before->key) IS DISTINCT FROM a.value
    ) diff;
    -- No effective change => skip
    IF v_changed IS NULL OR array_length(v_changed, 1) IS NULL THEN
      RETURN NEW;
    END IF;
  END IF;

  INSERT INTO public.audit_logs(actor_id, action, target_type, target_id, detail)
  VALUES (
    v_actor,
    TG_TABLE_NAME || '.' || TG_OP,
    TG_TABLE_NAME,
    v_target,
    jsonb_strip_nulls(jsonb_build_object(
      'op', TG_OP,
      'table', TG_TABLE_NAME,
      'via', v_via,
      'expert_id', v_expert,
      'before', v_before,
      'after', v_after,
      'changed', to_jsonb(v_changed)
    ))
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'audit_row_change failed for % %: %', TG_TABLE_NAME, TG_OP, SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.backfill_job_set_done(_id bigint, _status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.backfill_job_queue
  SET status = _status,
      updated_at = now(),
      fulfilled_at = CASE WHEN _status IN ('done','skipped') THEN now() ELSE fulfilled_at END
  WHERE id = _id;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.backfill_job_set_failed(_id bigint, _error text, _retry_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  job public.backfill_job_queue;
BEGIN
  SELECT * INTO job FROM public.backfill_job_queue WHERE id = _id;
  IF NOT FOUND THEN RETURN; END IF;

  IF job.attempts >= job.max_attempts THEN
    UPDATE public.backfill_job_queue
    SET status = 'failed',
        last_error = _error,
        updated_at = now()
    WHERE id = _id;
  ELSE
    UPDATE public.backfill_job_queue
    SET status = 'pending',
        last_error = _error,
        next_run_at = COALESCE(_retry_at, now() + (interval '1 minute' * (job.attempts + 1))),
        updated_at = now()
    WHERE id = _id;
  END IF;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.backfill_legacy_bsr_to_fact(_from date, _to date)
 RETURNS TABLE(inserted_rows integer, skipped_rows integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inserted int := 0;
  v_total int := 0;
BEGIN
  IF _from IS NULL OR _to IS NULL OR _from > _to THEN
    RAISE EXCEPTION 'Invalid date range: % to %', _from, _to;
  END IF;

  SELECT COUNT(*) INTO v_total
  FROM public.tw_bsr_daily
  WHERE trade_date BETWEEN _from AND _to;

  PERFORM set_config('app.force_reseal', 'true', true);

  WITH ins AS (
    INSERT INTO public.tw_chip_fact (
      stock_id, trade_date, broker_id, broker_name, source,
      buy_shares, sell_shares,
      avg_buy_price, avg_sell_price, ingested_at
    )
    SELECT
      stock_id, trade_date, broker_id, broker_name,
      'legacy_migration'::text,
      buy_shares, sell_shares,
      avg_buy_price, avg_sell_price,
      COALESCE(created_at, now())
    FROM public.tw_bsr_daily
    WHERE trade_date BETWEEN _from AND _to
    ON CONFLICT (stock_id, trade_date, broker_id, source) DO NOTHING
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_inserted FROM ins;

  PERFORM set_config('app.force_reseal', 'false', true);

  RETURN QUERY SELECT v_inserted, GREATEST(v_total - v_inserted, 0);
END;
$function$
