DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_apply_degrade_transition(_api text, _to_mode text, _reason text, _trigger_metric text, _trigger_value numeric, _threshold numeric, _cooldown_seconds integer, _correlation_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(from_mode text, to_mode text, applied boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _from text := 'normal';
  _now timestamptz := now();
  _cooldown timestamptz;
  _cfg jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('bsr_degrade_' || _api));

  SELECT COALESCE(config->>'mode', 'normal') INTO _from
    FROM public.tw_bsr_sync_config WHERE key = 'degrade:' || _api;
  IF _from IS NULL THEN _from := 'normal'; END IF;

  IF _from = _to_mode THEN
    RETURN QUERY SELECT _from, _to_mode, false;
    RETURN;
  END IF;

  _cooldown := _now + make_interval(secs => GREATEST(0, COALESCE(_cooldown_seconds, 600)));
  _cfg := jsonb_build_object(
      'mode', _to_mode,
      'since', _now,
      'reason', _reason,
      'trigger_metric', _trigger_metric,
      'trigger_value', _trigger_value,
      'threshold', _threshold,
      'last_transition_at', _now,
      'cooldown_until', _cooldown,
      'previous_mode', _from
    );

  -- 直接 UPDATE：trigger 會自動遞增 version 並寫 history
  UPDATE public.tw_bsr_sync_config
     SET config = _cfg, note = 'auto-degrade', updated_at = _now
   WHERE key = 'degrade:' || _api;

  IF NOT FOUND THEN
    INSERT INTO public.tw_bsr_sync_config(key, config, note)
    VALUES ('degrade:' || _api, _cfg, 'auto-degrade');
  END IF;

  INSERT INTO public.tw_bsr_degrade_events(api_name, from_mode, to_mode, reason, trigger_metric, trigger_value, threshold, correlation_id, detail)
  VALUES (_api, _from, _to_mode, _reason, _trigger_metric, _trigger_value, _threshold, _correlation_id, '{}'::jsonb);

  RETURN QUERY SELECT _from, _to_mode, true;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_backlog_metrics()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH tpe AS (
  SELECT (now() AT TIME ZONE 'Asia/Taipei')::date AS today_tw
), a AS (
  SELECT count(*)                                                        AS ready_pending_count,
         min(next_run_at)                                                AS oldest_due_since_ts,
         COALESCE(EXTRACT(epoch FROM (now() - min(next_run_at)))/3600.0, 0) AS oldest_due_since_h,
         COALESCE(EXTRACT(epoch FROM (now() - min(enqueued_at)))/3600.0, 0) AS oldest_ready_enqueued_h
    FROM public.tw_bsr_sync_queue
   WHERE status = 'pending' AND next_run_at IS NOT NULL AND next_run_at <= now()
), a_null AS (
  SELECT count(*) AS unclaimable_null_count
    FROM public.tw_bsr_sync_queue
   WHERE status = 'pending' AND next_run_at IS NULL
), b AS (
  SELECT count(*)                                                        AS deferred_count,
         min(next_run_at)                                                AS next_ready_at,
         COALESCE(EXTRACT(epoch FROM (now() - min(enqueued_at)))/3600.0, 0) AS oldest_enqueued_age_h
    FROM public.tw_bsr_sync_queue
   WHERE status = 'pending' AND next_run_at IS NOT NULL AND next_run_at > now()
), cohort AS (
  SELECT q.id, q.stock_id, q.trade_date, q.priority, q.enqueued_at, q.max_attempts
    FROM public.tw_bsr_sync_queue q
   WHERE q.status = 'failed'
     AND (q.last_error LIKE 'finmind_admission_%' OR q.last_error = 'quota_deferred')
), stocks AS (
  SELECT DISTINCT stock_id FROM cohort
), ready5 AS (
  SELECT s.stock_id, x.have5
    FROM stocks s CROSS JOIN tpe
    CROSS JOIN LATERAL (
      SELECT count(DISTINCT f.trade_date) AS have5
        FROM public.tw_chip_fact f
       WHERE f.stock_id = s.stock_id AND f.trade_date >= tpe.today_tw - 10
    ) x
), classified AS (
  SELECT c.*,
         EXISTS (SELECT 1 FROM public.tw_chip_fact f
                  WHERE f.stock_id = c.stock_id AND f.trade_date = c.trade_date) AS has_fact,
         COALESCE(r.have5, 0) AS have5
    FROM cohort c
    LEFT JOIN ready5 r ON r.stock_id = c.stock_id
), c AS (
  SELECT count(*)                                              AS legacy_quota_failed_total,
         count(*) FILTER (WHERE has_fact)                      AS satisfied_reconcilable,
         count(*) FILTER (
           WHERE NOT has_fact
             AND (trade_date = public.expected_latest_bsr_date()
                  OR (trade_date >= (SELECT today_tw FROM tpe) - 10 AND have5 < 5))
         )                                                     AS actionable_still_required,
         count(*) FILTER (
           WHERE NOT has_fact
             AND NOT (trade_date = public.expected_latest_bsr_date()
                      OR (trade_date >= (SELECT today_tw FROM tpe) - 10 AND have5 < 5))
         )                                                     AS obsolete_retained,
         count(*) FILTER (
           WHERE NOT has_fact
             AND max_attempts < 8
             AND (trade_date = public.expected_latest_bsr_date()
                  OR (trade_date >= (SELECT today_tw FROM tpe) - 10 AND have5 < 5))
         )                                                     AS actionable_token_eligible
    FROM classified
), d AS (
  SELECT COALESCE(sum(COALESCE(row_count, 0)), 0)                                       AS tokens_issued_24h,
         COALESCE(sum(COALESCE((metadata->>'reconciled')::int, 0)), 0)                  AS reconciled_24h,
         (SELECT metadata->>'budget_reason' FROM public.data_source_refresh_logs
           WHERE source_key = 'bsr_quota_recovery' ORDER BY created_at DESC LIMIT 1)    AS last_budget_reason,
         (SELECT metadata->>'next_admission_at' FROM public.data_source_refresh_logs
           WHERE source_key = 'bsr_quota_recovery' ORDER BY created_at DESC LIMIT 1)    AS last_next_admission_at
    FROM public.data_source_refresh_logs
   WHERE source_key = 'bsr_quota_recovery' AND created_at >= now() - interval '24 hours'
)
SELECT jsonb_build_object(
  'ready', jsonb_build_object(
     'ready_pending_count', a.ready_pending_count,
     'oldest_due_since_ts', a.oldest_due_since_ts,
     'oldest_due_since_h', round(a.oldest_due_since_h::numeric, 2),
     'oldest_ready_enqueued_h', round(a.oldest_ready_enqueued_h::numeric, 2),
     'unclaimable_null_count', a_null.unclaimable_null_count
  ),
  'deferred', jsonb_build_object(
     'deferred_count', b.deferred_count,
     'next_ready_at', b.next_ready_at,
     'oldest_enqueued_age_h', round(b.oldest_enqueued_age_h::numeric, 2)
  ),
  'cohort', jsonb_build_object(
     'legacy_quota_failed_total', c.legacy_quota_failed_total,
     'satisfied_reconcilable', c.satisfied_reconcilable,
     'actionable_still_required', c.actionable_still_required,
     'actionable_token_eligible', c.actionable_token_eligible,
     'obsolete_retained', c.obsolete_retained,
     'counting_mode', 'exact'
  ),
  'audit', jsonb_build_object(
     'tokens_issued_24h', d.tokens_issued_24h,
     'reconciled_24h', d.reconciled_24h,
     'last_budget_reason', d.last_budget_reason,
     'last_next_admission_at', d.last_next_admission_at
  ),
  'generated_at', now()
)
FROM a, a_null, b, c, d;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_check_tier_admission(_api text DEFAULT 'finmind'::text, _tier smallint DEFAULT 3, _limit integer DEFAULT 1500)
 RETURNS TABLE(allowed boolean, reason text, hourly_used integer, tier_used integer, tier_guarantee integer, available_for_tier integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_since timestamptz := now() - interval '1 hour';
  v_used  integer;
  v_used_t1 integer;
  v_used_t2 integer;
  v_used_t3 integer;
  v_g1 integer := (_limit * 40) / 100;
  v_g2 integer := (_limit * 20) / 100;
  v_g3 integer := (_limit *  5) / 100;
  v_tier_used integer;
  v_tier_g integer;
  v_reserved_by_higher integer;
  v_available integer;
BEGIN
  SELECT COUNT(*) INTO v_used
    FROM public.tw_bsr_api_reservations
   WHERE api_name = _api AND reserved_at >= v_since AND released = false
     AND (settled_at IS NOT NULL OR expires_at > now());

  SELECT
    COUNT(*) FILTER (WHERE tier = 1),
    COUNT(*) FILTER (WHERE tier = 2),
    COUNT(*) FILTER (WHERE tier = 3 OR tier IS NULL)
  INTO v_used_t1, v_used_t2, v_used_t3
    FROM public.tw_bsr_api_reservations
   WHERE api_name = _api AND reserved_at >= v_since AND released = false
     AND (settled_at IS NOT NULL OR expires_at > now());

  IF _tier = 1 THEN
    v_tier_used := v_used_t1; v_tier_g := v_g1; v_reserved_by_higher := 0;
  ELSIF _tier = 2 THEN
    v_tier_used := v_used_t2; v_tier_g := v_g2;
    v_reserved_by_higher := GREATEST(0, v_g1 - v_used_t1);
  ELSE
    v_tier_used := v_used_t3; v_tier_g := v_g3;
    v_reserved_by_higher := GREATEST(0, v_g1 - v_used_t1) + GREATEST(0, v_g2 - v_used_t2);
  END IF;

  v_available := _limit - v_used - v_reserved_by_higher;

  IF v_available > 0 THEN
    RETURN QUERY SELECT true, 'ok'::text, v_used, v_tier_used, v_tier_g, v_available;
    RETURN;
  END IF;

  IF v_tier_used < v_tier_g THEN
    RETURN QUERY SELECT true, 'min_guarantee'::text, v_used, v_tier_used, v_tier_g,
                        v_tier_g - v_tier_used;
    RETURN;
  END IF;

  RETURN QUERY SELECT false, 'squeezed_by_higher_tier'::text, v_used, v_tier_used, v_tier_g, 0;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_force_recycle_reservation(_reservation_id bigint, _reason text DEFAULT 'manual_force_recycle'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE _n int;
BEGIN
  UPDATE public.tw_bsr_api_reservations
     SET released = true, settled_at = now(),
         recycle_reason = COALESCE(recycle_reason, _reason)
   WHERE id = _reservation_id
     AND settled_at IS NULL
     AND released = false;
  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n > 0;
END;
$function$
