DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_list_stuck_reservations(_api text DEFAULT 'finmind'::text, _min_age_seconds integer DEFAULT 30, _limit integer DEFAULT 50)
 RETURNS TABLE(id bigint, correlation_id uuid, reserved_at timestamp with time zone, expires_at timestamp with time zone, age_seconds integer, expired boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT id, correlation_id, reserved_at, expires_at,
         EXTRACT(EPOCH FROM (now() - reserved_at))::int AS age_seconds,
         (expires_at < now()) AS expired
    FROM public.tw_bsr_api_reservations
   WHERE api_name = _api
     AND settled_at IS NULL
     AND released = false
     AND (now() - reserved_at) >= make_interval(secs => _min_age_seconds)
   ORDER BY reserved_at ASC
   LIMIT _limit;
$function$
