 RETURNS TABLE(id bigint, from_mode text, to_mode text, reason text, trigger_metric text, trigger_value numeric, threshold numeric, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
