DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_recovery_budget(p_full_budget integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_metrics jsonb;
  v_ks boolean;
  v_mode text;
  v_reason text;
  v_ready int;
  v_oldest numeric;
  v_level text;
  v_budget int;
  v_breason text;
  v_pools jsonb;
  v_any_pool_ok boolean := false;
  v_next_admission timestamptz;
  DAILY_RESERVE constant int := 30;
  BURST_RESERVE constant int := 30;
BEGIN
  v_metrics := public.bsr_backlog_metrics();
  v_ready  := COALESCE((v_metrics#>>'{ready,ready_pending_count}')::int, 0);
  v_oldest := COALESCE((v_metrics#>>'{ready,oldest_due_since_h}')::numeric, 0);

  SELECT public.check_kill_switch('chips_all') INTO v_ks;
  SELECT mode, reason INTO v_mode, v_reason FROM public.bsr_get_degrade_state('finmind');
  v_mode := COALESCE(v_mode, 'normal');
  v_reason := COALESCE(v_reason, '');

  -- pool snapshot (canary: interactive excluded, it is the user-facing drawer path)
  SELECT jsonb_agg(jsonb_build_object(
           'pool', pool_name,
           'tokens', floor(tokens),
           'used_today', used_today,
           'daily_budget', daily_budget,
           'reset_at', reset_at,
           'excluded', pool_name = 'interactive',
           'issue_ok', pool_name <> 'interactive'
                        AND used_today + 1 <= daily_budget - DAILY_RESERVE
                        AND floor(tokens) >= BURST_RESERVE + 1
         ) ORDER BY pool_name)
    INTO v_pools
    FROM public.finmind_quota_pools;

  SELECT bool_or((p->>'issue_ok')::boolean) INTO v_any_pool_ok
    FROM jsonb_array_elements(COALESCE(v_pools, '[]'::jsonb)) p;

  SELECT min(((reset_at + 1)::timestamp) AT TIME ZONE 'Asia/Taipei')
    INTO v_next_admission
    FROM public.finmind_quota_pools
   WHERE pool_name <> 'interactive';

  IF v_ks IS NOT TRUE THEN
    v_level := 'halted'; v_budget := 0; v_breason := 'kill_switch';
  ELSIF v_mode IN ('claim_halt', 'p1_only') THEN
    v_level := 'halted'; v_budget := 0; v_breason := 'degrade_' || v_mode;
  ELSIF v_mode = 'tier2_paused' THEN
    v_level := 'halted'; v_budget := 0; v_breason := 'degrade_tier2_paused';
  ELSIF v_mode = 'tier3_paused' AND v_reason = 'reservation_stuck' THEN
    v_level := 'halted'; v_budget := 0; v_breason := 'degrade_reservation_stuck';
  ELSIF COALESCE(v_any_pool_ok, false) IS NOT TRUE THEN
    v_level := 'pool_blocked'; v_budget := 0; v_breason := 'pool_reserve_blocked';
  ELSE
    -- capacity caps only; p1_stalled must NOT zero the budget (symptom, not cause)
    v_level := 'canary';
    v_budget := LEAST(1, GREATEST(0, COALESCE(p_full_budget, 12)));
    v_breason := 'cap_1';
    IF v_ready > 600 OR (v_mode = 'tier3_paused' AND v_reason = 'usage_ge_80') THEN
      v_level := 'capped';
      v_budget := LEAST(1, v_budget);
    END IF;
    IF v_budget = 0 THEN v_breason := 'cap_zero'; END IF;
  END IF;

  RETURN jsonb_build_object(
    'level', v_level,
    'budget', v_budget,
    'budget_reason', v_breason,
    'degrade', jsonb_build_object('mode', v_mode, 'reason', v_reason),
    'kill_switch_on', v_ks,
    'pools', COALESCE(v_pools, '[]'::jsonb),
    'next_admission_at', v_next_admission,
    'pending_ready', v_ready,
    'oldest_due_since_h', v_oldest,
    'metrics', v_metrics
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_reservation_stats(_api text DEFAULT 'finmind'::text)
 RETURNS TABLE(in_flight integer, expiring_soon integer, expired_unsettled integer, settled_last_hour integer, rate_limited_last_hour integer, oldest_in_flight_age_seconds integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    (SELECT count(*)::int FROM public.tw_bsr_api_reservations
       WHERE api_name = _api AND settled_at IS NULL AND released = false
         AND expires_at > now()) AS in_flight,
    (SELECT count(*)::int FROM public.tw_bsr_api_reservations
       WHERE api_name = _api AND settled_at IS NULL AND released = false
         AND expires_at > now() AND expires_at <= now() + interval '10 seconds') AS expiring_soon,
    (SELECT count(*)::int FROM public.tw_bsr_api_reservations
       WHERE api_name = _api AND settled_at IS NULL AND released = false
         AND expires_at <= now()) AS expired_unsettled,
    (SELECT count(*)::int FROM public.tw_bsr_api_reservations
       WHERE api_name = _api AND settled_at IS NOT NULL
         AND settled_at >= now() - interval '1 hour') AS settled_last_hour,
    (SELECT COALESCE(sum(rate_limited_count),0)::int FROM public.tw_bsr_api_usage
       WHERE api_name = _api AND bucket_start >= now() - interval '1 hour') AS rate_limited_last_hour,
    (SELECT COALESCE(EXTRACT(EPOCH FROM (now() - min(reserved_at)))::int, 0)
       FROM public.tw_bsr_api_reservations
      WHERE api_name = _api AND settled_at IS NULL AND released = false
        AND expires_at > now()) AS oldest_in_flight_age_seconds;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_snapshot_claim(_trade_date date, _correlation_id uuid, _lease_seconds integer DEFAULT 90)
 RETURNS TABLE(claimed boolean, prev_status text, attempt_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev text;
  v_new_attempts integer;
BEGIN
  INSERT INTO public.tw_bsr_daily_snapshot_status(trade_date, status)
  VALUES (_trade_date, 'pending')
  ON CONFLICT (trade_date) DO NOTHING;

  SELECT status INTO v_prev
    FROM public.tw_bsr_daily_snapshot_status WHERE trade_date = _trade_date;

  IF v_prev IN ('ready','exhausted') THEN
    RETURN QUERY SELECT false, v_prev, 0;
    RETURN;
  END IF;

  UPDATE public.tw_bsr_daily_snapshot_status
     SET status = 'fetching',
         correlation_id = _correlation_id,
         lock_expires_at = now() + make_interval(secs => _lease_seconds),
         attempt_count = attempt_count + 1
   WHERE trade_date = _trade_date
     AND (
       status IN ('pending','partial','failed')
       OR (status = 'fetching' AND (lock_expires_at IS NULL OR lock_expires_at < now()))
     )
   RETURNING attempt_count INTO v_new_attempts;

  IF FOUND THEN
    RETURN QUERY SELECT true, v_prev, v_new_attempts;
  ELSE
    RETURN QUERY SELECT false, v_prev, 0;
  END IF;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_snapshot_fulfill_jobs(_trade_date date, _threshold integer DEFAULT 5)
 RETURNS TABLE(fulfilled integer, still_pending integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_done integer;
  v_pending integer;
BEGIN
  WITH sufficient AS (
    SELECT stock_id
      FROM public.tw_bsr_daily
     WHERE trade_date = _trade_date
     GROUP BY stock_id
    HAVING COUNT(*) >= _threshold
  ),
  updated AS (
    UPDATE public.tw_bsr_sync_queue q
       SET status = 'done',
           finished_at = now(),
           last_success_at = now(),
           last_error = NULL,
           next_run_at = now()
      FROM sufficient s
     WHERE q.trade_date = _trade_date
       AND q.stock_id = s.stock_id
       AND q.status IN ('pending','running')
     RETURNING q.id
  )
  SELECT COUNT(*) INTO v_done FROM updated;

  SELECT COUNT(*) INTO v_pending
    FROM public.tw_bsr_sync_queue
   WHERE trade_date = _trade_date AND status IN ('pending','running');

  RETURN QUERY SELECT COALESCE(v_done, 0)::integer, COALESCE(v_pending, 0)::integer;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.bsr_snapshot_mark(_trade_date date, _status text, _source text, _coverage_stocks integer, _coverage_rows integer, _last_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
