DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.calculate_expert_performance(_expert_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result jsonb;
  total_trades integer := 0;
  winning_trades integer := 0;
  avg_pnl_pct numeric := 0;
  avg_hold numeric := 0;
  rec record;
  peak_amt numeric := 0;
  running_amt numeric := 0;
  worst_dd_amt numeric := 0;
  one_year_ago timestamp with time zone := NOW() - INTERVAL '1 year';
  return_1y numeric := 0;
  v_starting_capital numeric := 0;
  v_realized_amount numeric := 0;
  v_unrealized_amount numeric := 0;
  v_open_market_value numeric := 0;
  v_open_cost_value numeric := 0;
  v_current_asset numeric := 0;
  v_total_return_pct numeric := 0;
  v_max_drawdown_pct numeric := 0;
  v_profit_sum_amt numeric := 0;
  v_loss_sum_amt numeric := 0;
  v_profit_factor numeric := 0;
  v_avg_pnl_amount numeric := 0;
BEGIN
  -- starting capital
  SELECT COALESCE(starting_capital, 0) INTO v_starting_capital
  FROM public.experts WHERE id = _expert_id;

  -- closed-trade aggregates: count, win, avg pnl%, realized $, profit/loss $
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE pnl_percent > 0),
    COALESCE(AVG(pnl_percent), 0),
    COALESCE(SUM(
      COALESCE(quantity, 0) * (COALESCE(exit_price, entry_price, 0) - COALESCE(entry_price, 0))
    ), 0),
    COALESCE(SUM(
      COALESCE(quantity, 0) * (COALESCE(exit_price, entry_price, 0) - COALESCE(entry_price, 0))
    ) FILTER (WHERE COALESCE(quantity, 0) * (COALESCE(exit_price, entry_price, 0) - COALESCE(entry_price, 0)) > 0), 0),
    COALESCE(ABS(SUM(
      COALESCE(quantity, 0) * (COALESCE(exit_price, entry_price, 0) - COALESCE(entry_price, 0))
    ) FILTER (WHERE COALESCE(quantity, 0) * (COALESCE(exit_price, entry_price, 0) - COALESCE(entry_price, 0)) < 0)), 0)
  INTO total_trades, winning_trades, avg_pnl_pct, v_realized_amount, v_profit_sum_amt, v_loss_sum_amt
  FROM public.trade_records
  WHERE expert_id = _expert_id AND status IN ('closed', 'stopped');

  -- max drawdown: running pnl_amount cumulative (closed trades, ordered)
  FOR rec IN
    SELECT (COALESCE(quantity, 0) * (COALESCE(exit_price, entry_price, 0) - COALESCE(entry_price, 0))) AS pnl_amt
    FROM public.trade_records
    WHERE expert_id = _expert_id AND status IN ('closed', 'stopped')
    ORDER BY exit_date ASC NULLS LAST, created_at ASC
  LOOP
    running_amt := running_amt + rec.pnl_amt;
    IF running_amt > peak_amt THEN peak_amt := running_amt; END IF;
    IF (peak_amt - running_amt) > worst_dd_amt THEN worst_dd_amt := peak_amt - running_amt; END IF;
  END LOOP;

  -- 1-year return: sum of pnl_amount in $ / starting_capital × 100
  SELECT COALESCE(SUM(
    COALESCE(quantity, 0) * (COALESCE(exit_price, entry_price, 0) - COALESCE(entry_price, 0))
  ), 0)
  INTO return_1y
  FROM public.trade_records
  WHERE expert_id = _expert_id AND status IN ('closed', 'stopped')
    AND exit_date >= one_year_ago;

  -- avg hold days: include open trades (treat NOW() as exit)
  SELECT COALESCE(AVG(
    EXTRACT(EPOCH FROM (COALESCE(exit_date, NOW()) - entry_date)) / 86400
  ), 0)
  INTO avg_hold
  FROM public.trade_records
  WHERE expert_id = _expert_id AND status IN ('open', 'closed', 'stopped');

  -- unrealized: open trades market value vs cost
  SELECT
    COALESCE(SUM(tr.quantity * COALESCE(cp.price, tr.current_price, tr.entry_price, 0)), 0),
    COALESCE(SUM(tr.quantity * COALESCE(tr.entry_price, 0)), 0)
  INTO v_open_market_value, v_open_cost_value
  FROM public.trade_records tr
  LEFT JOIN public.current_prices cp ON cp.symbol = SPLIT_PART(tr.instrument, ' ', 1)
  WHERE tr.expert_id = _expert_id AND tr.status = 'open';

  v_unrealized_amount := v_open_market_value - v_open_cost_value;

  IF v_starting_capital > 0 THEN
    v_current_asset := v_starting_capital + v_realized_amount + v_unrealized_amount;
    v_total_return_pct := ROUND(((v_realized_amount + v_unrealized_amount) / v_starting_capital) * 100, 2);
    v_max_drawdown_pct := ROUND((worst_dd_amt / v_starting_capital) * 100, 2);
  ELSE
    v_current_asset := v_open_market_value;
    v_total_return_pct := 0;
    v_max_drawdown_pct := 0;
  END IF;

  -- profit factor in $
  IF v_loss_sum_amt > 0 THEN
    v_profit_factor := ROUND(v_profit_sum_amt / v_loss_sum_amt, 2);
  ELSIF v_profit_sum_amt > 0 THEN
    v_profit_factor := 999.99;
  ELSE
    v_profit_factor := 0;
  END IF;

  IF total_trades > 0 THEN
    v_avg_pnl_amount := ROUND(v_realized_amount / total_trades, 0);
  END IF;

  result := jsonb_build_object(
    'total_trades', total_trades,
    'win_rate', CASE WHEN total_trades > 0 THEN ROUND((winning_trades::numeric / total_trades) * 100, 2) ELSE 0 END,
    'avg_pnl_pct', ROUND(avg_pnl_pct, 2),
    'avg_pnl_amount', v_avg_pnl_amount,
    'max_drawdown', v_max_drawdown_pct,
    'profit_factor', v_profit_factor,
    'avg_hold_days', ROUND(avg_hold, 1),
    'return_1y', CASE WHEN v_starting_capital > 0 THEN ROUND((return_1y / v_starting_capital) * 100, 2) ELSE 0 END,
    'current_asset', ROUND(v_current_asset, 0),
    'starting_capital', ROUND(v_starting_capital, 0),
    'realized_pnl_amount', ROUND(v_realized_amount, 0),
    'unrealized_pnl_amount', ROUND(v_unrealized_amount, 0),
    'total_return_pct', v_total_return_pct
  );

  RETURN result;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.check_bsr_rate_limit(_limit integer DEFAULT 1500, _api text DEFAULT 'finmind'::text)
 RETURNS TABLE(used integer, remaining integer, allowed boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  _usage int;
  _active_res int;
  _total int;
BEGIN
  SELECT COALESCE(SUM(call_count), 0)::int INTO _usage
    FROM public.tw_bsr_api_usage
   WHERE api_name = _api
     AND bucket_start >= now() - interval '60 minutes';

  SELECT COUNT(*)::int INTO _active_res
    FROM public.tw_bsr_api_reservations
   WHERE api_name = _api
     AND settled_at IS NULL
     AND released = false
     AND reserved_at >= now() - interval '60 minutes'
     AND expires_at >= now();

  _total := _usage + _active_res;
  used := _total;
  remaining := GREATEST(0, _limit - _total);
  allowed := _total < _limit;
  RETURN NEXT;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.check_checkup_quota(_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tier text := 'none';
  v_period text := 'month';
  v_base_limit int := 0;
  v_used int := 0;
  v_period_start timestamptz;
  v_resets_at timestamptz;
  v_last_used_at timestamptz := NULL;
  v_is_tester boolean := false;
  v_now_tw timestamp;
  v_email text;
  v_is_line boolean := false;
  v_entitlement_total int := 0;
  v_total_limit int := 0;
  v_total_remaining int := 0;
BEGIN
  SELECT COALESCE(p.is_tester, false) INTO v_is_tester
    FROM public.profiles p WHERE p.user_id = _user_id LIMIT 1;

  IF v_is_tester THEN
    v_tier := 'pro'; v_period := 'month'; v_base_limit := 22;
  ELSE
    SELECT cp.tier, cp.quota_period, cp.monthly_quota
      INTO v_tier, v_period, v_base_limit
      FROM public.checkup_subscriptions cs
      JOIN public.checkup_plans cp ON cp.id = cs.plan_id
     WHERE cs.user_id = _user_id
       AND cs.status = 'active'
       AND (cs.expires_at IS NULL OR cs.expires_at > now())
     ORDER BY cp.sort_order DESC LIMIT 1;

    IF v_tier IS NULL THEN
      SELECT email INTO v_email FROM auth.users WHERE id = _user_id LIMIT 1;
      v_is_line := v_email IS NOT NULL AND v_email LIKE 'line_%@line.local';
      IF v_is_line THEN
        v_tier := 'line_free'; v_period := 'lifetime'; v_base_limit := 1;
      ELSE
        v_tier := 'none'; v_period := 'month'; v_base_limit := 0;
      END IF;
    END IF;
  END IF;

  v_now_tw := (now() AT TIME ZONE 'Asia/Taipei');
  IF v_period = 'lifetime' THEN
    v_period_start := 'epoch'::timestamptz;
    v_resets_at := 'infinity'::timestamptz;
  ELSIF v_period = 'week' THEN
    v_period_start := (date_trunc('week', v_now_tw) AT TIME ZONE 'Asia/Taipei');
    v_resets_at := v_period_start + INTERVAL '7 days';
  ELSE
    v_period_start := (date_trunc('month', v_now_tw) AT TIME ZONE 'Asia/Taipei');
    v_resets_at := ((date_trunc('month', v_now_tw) + INTERVAL '1 month') AT TIME ZONE 'Asia/Taipei');
  END IF;

  BEGIN
    SELECT COALESCE(COUNT(*) FILTER (WHERE used_at >= v_period_start), 0)::int,
           MAX(used_at) FILTER (WHERE used_at >= v_period_start)
      INTO v_used, v_last_used_at
      FROM public.checkup_usage
     WHERE user_id = _user_id
       AND kind = 'daily-analysis';
  EXCEPTION WHEN OTHERS THEN
    v_used := 0; v_last_used_at := NULL;
  END;

  SELECT COALESCE(SUM(amount), 0)::int INTO v_entitlement_total
    FROM public.checkup_entitlements
   WHERE user_id = _user_id
     AND is_active = true
     AND (expires_at IS NULL OR expires_at > now());

  v_total_limit := v_base_limit + v_entitlement_total;
  v_total_remaining := GREATEST(v_total_limit - v_used, 0);

  RETURN jsonb_build_object(
    'tier', v_tier,
    'period', v_period,
    'limit', v_total_limit,
    'base_limit', v_base_limit,
    'entitlement_total', v_entitlement_total,
    'used', COALESCE(v_used, 0),
    'remaining', v_total_remaining,
    'resets_at', v_resets_at,
    'last_used_at', v_last_used_at
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
