DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.checkup_prefetch_universe()
 RETURNS TABLE(code text, supported boolean, reason text, sources text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH raw AS (
    SELECT upper(btrim((regexp_match(split_part(tr.instrument,' ',1), '^([0-9A-Z]{4,6})'))[1])) AS code,
           'trade_records'::text AS src
      FROM public.trade_records tr
     WHERE COALESCE(upper(tr.market),'TW') IN ('TW','TWSE','TPEX','')
       AND split_part(tr.instrument,' ',1) ~ '^[0-9]'
    UNION ALL
    SELECT upper(btrim((regexp_match(split_part(es.instrument,' ',1), '^([0-9A-Z]{4,6})'))[1])),
           'expert_signals'
      FROM public.expert_signals es
     WHERE es.published_at IS NOT NULL
       AND COALESCE(upper(es.market),'TW') IN ('TW','TWSE','TPEX','')
       AND split_part(es.instrument,' ',1) ~ '^[0-9]'
    UNION ALL
    SELECT upper(btrim(COALESCE(h->>'code', h->>'symbol'))), 'checkup_storage'
      FROM public.checkup_storage cs,
           LATERAL jsonb_array_elements(
             CASE
               WHEN jsonb_typeof(cs.data) = 'array' THEN cs.data
               WHEN jsonb_typeof(cs.data->'holdings') = 'array' THEN cs.data->'holdings'
               ELSE '[]'::jsonb
             END
           ) h
     WHERE cs.key = 'pf-holdings-v2'
    UNION ALL
    SELECT upper(btrim(t.code)), 'registry'
      FROM public.chips_prefetch_targets t
     WHERE t.active
  ),
  norm AS (
    SELECT code, src FROM raw WHERE code IS NOT NULL AND code <> ''
  ),
  agg AS (
    SELECT code, array_agg(DISTINCT src ORDER BY src) AS sources
      FROM norm GROUP BY code
  )
  SELECT a.code,
         COALESCE((public.tw_bsr_eligibility(a.code)->>'eligible')::boolean, false) AS supported,
         public.tw_bsr_eligibility(a.code)->>'ineligible_reason' AS reason,
         a.sources
    FROM agg a;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.chip_fact_summary(_days integer DEFAULT 20)
 RETURNS TABLE(total_rows bigint, distinct_stocks bigint, distinct_days bigint, last_fact_at timestamp with time zone, broker_scraper_rows bigint, finmind_batch_rows bigint, finmind_per_stock_rows bigint, legacy_migration_rows bigint, sealed_days bigint, eligible_days bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH cutoff AS (
    SELECT (CURRENT_DATE - make_interval(days => _days))::date AS d
  ),
  fact AS (
    SELECT *
    FROM public.tw_chip_fact, cutoff
    WHERE trade_date >= cutoff.d
  ),
  ss AS (
    SELECT trade_date, sealed_at
    FROM public.tw_bsr_daily_snapshot_status, cutoff
    WHERE trade_date >= cutoff.d
  )
  SELECT
    (SELECT COUNT(*) FROM fact),
    (SELECT COUNT(DISTINCT stock_id) FROM fact),
    (SELECT COUNT(DISTINCT trade_date) FROM fact),
    (SELECT MAX(ingested_at) FROM fact),
    (SELECT COUNT(*) FROM fact WHERE source = 'broker_scraper'),
    (SELECT COUNT(*) FROM fact WHERE source = 'finmind_batch'),
    (SELECT COUNT(*) FROM fact WHERE source = 'finmind_per_stock'),
    (SELECT COUNT(*) FROM fact WHERE source = 'legacy_migration'),
    (SELECT COUNT(*) FROM ss WHERE sealed_at IS NOT NULL),
    (SELECT COUNT(*) FROM ss);
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
