DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.claim_backfill_jobs(_batch_size integer DEFAULT 1, _max_priority_score integer DEFAULT NULL::integer)
 RETURNS TABLE(id bigint, dataset text, stock_id text, start_date date, end_date date, source_hint text, payload jsonb, attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  now_ts TIMESTAMPTZ := now();
BEGIN
  PERFORM public.recover_stale_backfill_jobs(interval '15 minutes');

  RETURN QUERY
  WITH claimed AS (
    SELECT q.id
    FROM public.backfill_job_queue q
    WHERE q.status = 'pending'
      AND q.next_run_at <= now_ts
      AND (_max_priority_score IS NULL OR q.priority_score <= _max_priority_score)
    ORDER BY q.priority_score DESC, q.next_run_at ASC, q.id ASC
    LIMIT GREATEST(1, LEAST(COALESCE(_batch_size, 1), 10))
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.backfill_job_queue q
  SET status = 'running',
      updated_at = now_ts,
      attempts = q.attempts + 1,
      last_error = NULL
  FROM claimed c
  WHERE q.id = c.id
  RETURNING q.id, q.dataset, q.stock_id, q.start_date, q.end_date, q.source_hint, q.payload, q.attempts;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.claim_bsr_queue_jobs(_batch integer DEFAULT 20, _max_priority integer DEFAULT 3)
 RETURNS SETOF tw_bsr_sync_queue
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  in_hours boolean := public.is_tw_trading_hours();
BEGIN
  RETURN QUERY
  WITH token_slot AS (
    SELECT id FROM public.tw_bsr_sync_queue
    WHERE status = 'pending'
      AND priority <= _max_priority
      AND next_run_at <= now()
      AND (NOT in_hours OR post_close_only = false)
      AND last_error = 'quota_recovery_token'
    ORDER BY next_run_at ASC, id ASC
    FOR UPDATE SKIP LOCKED
    LIMIT LEAST(1, GREATEST(_batch, 0))
  ),
  normal AS (
    SELECT id FROM public.tw_bsr_sync_queue
    WHERE status = 'pending'
      AND priority <= _max_priority
      AND next_run_at <= now()
      AND (NOT in_hours OR post_close_only = false)
      AND last_error IS DISTINCT FROM 'quota_recovery_token'
    ORDER BY priority ASC, next_run_at ASC, id ASC
    FOR UPDATE SKIP LOCKED
    LIMIT GREATEST(_batch - (SELECT count(*) FROM token_slot), 0)
  ),
  picked AS (
    SELECT id, 0 AS bucket FROM token_slot
    UNION ALL
    SELECT id, 1 AS bucket FROM normal
  ),
  updated AS (
    UPDATE public.tw_bsr_sync_queue q
    SET status = 'running', started_at = now(), attempts = q.attempts + 1
    FROM picked
    WHERE q.id = picked.id
    RETURNING q.*
  )
  SELECT u.* FROM updated u
  JOIN picked p ON p.id = u.id
  ORDER BY p.bucket ASC, u.priority ASC, u.next_run_at ASC, u.id ASC;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.claim_institutional_new_stock(_lease_seconds integer DEFAULT 60)
 RETURNS TABLE(id uuid, stock_id text, attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.institutional_new_stock_queue q
     SET status='running', attempts=q.attempts+1,
         next_attempt_at=now() + make_interval(secs => _lease_seconds),
         updated_at=now()
   WHERE q.id = (
     SELECT q2.id FROM public.institutional_new_stock_queue q2
      WHERE q2.status='pending' AND q2.next_attempt_at <= now()
      ORDER BY q2.next_attempt_at ASC
      FOR UPDATE SKIP LOCKED LIMIT 1
   )
  RETURNING q.id, q.stock_id, q.attempts;
END;
