DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.defer_bsr_job_quota(p_job_id bigint, p_delay_minutes integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_delay int := GREATEST(1, LEAST(240, COALESCE(p_delay_minutes, 30)));
  v_row public.tw_bsr_sync_queue;
BEGIN
  UPDATE public.tw_bsr_sync_queue q
     SET status       = 'pending',
         attempts     = GREATEST(q.attempts - 1, 0),  -- 抵銷 claim 時的 +1
         started_at   = NULL,
         finished_at  = NULL,
         last_error   = 'quota_deferred',
         next_run_at  = now() + make_interval(mins => v_delay),
         updated_at   = now()
   WHERE q.id = p_job_id
     AND q.status = 'running'
  RETURNING q.* INTO v_row;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('deferred', false, 'reason', 'not_running', 'job_id', p_job_id);
  END IF;

  RETURN jsonb_build_object(
    'deferred', true,
    'job_id', v_row.id,
    'attempts', v_row.attempts,
    'next_run_at', v_row.next_run_at
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
