DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.derive_traffic_channel(_utm_medium text, _utm_source text, _referrer_host text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  m text := lower(coalesce(_utm_medium, ''));
  s text := lower(coalesce(_utm_source, ''));
  h text := lower(coalesce(_referrer_host, ''));
BEGIN
  IF m IN ('cpc','paid','ppc','display','paid-social','paidsocial','paid_social') THEN
    RETURN 'paid';
  END IF;
  IF m = 'email' OR s IN ('email','newsletter','edm') THEN
    RETURN 'email';
  END IF;
  IF m IN ('social','social-organic') OR s IN ('facebook','fb','instagram','ig','line','threads','x','twitter','tiktok','youtube','yt') THEN
    RETURN 'social';
  END IF;
  IF m = 'organic' OR s IN ('google','bing','yahoo','duckduckgo','baidu') THEN
    RETURN 'organic';
  END IF;
  IF h <> '' THEN
    IF h LIKE '%google.%' OR h LIKE '%bing.%' OR h LIKE '%yahoo.%' OR h LIKE '%duckduckgo.%' OR h LIKE '%baidu.%' THEN
      RETURN 'organic';
    END IF;
    IF h LIKE '%facebook.%' OR h LIKE '%instagram.%' OR h LIKE '%line.%' OR h LIKE '%t.co' OR h LIKE '%twitter.%' OR h LIKE '%x.com' OR h LIKE '%threads.%' OR h LIKE '%tiktok.%' OR h LIKE '%youtube.%' OR h LIKE '%youtu.be' THEN
      RETURN 'social';
    END IF;
    RETURN 'referral';
  END IF;
  RETURN 'direct';
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.detect_chip_gap_jobs(_target_date date DEFAULT CURRENT_DATE, _lookback_days integer DEFAULT 60, _max_jobs integer DEFAULT 5000)
 RETURNS TABLE(stock_id text, start_date date, end_date date, gap_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH uni AS (
    SELECT u.code AS symbol, u.sources FROM public.checkup_prefetch_universe() u WHERE u.supported
  ),
  open_tr AS (
    SELECT DISTINCT upper(btrim((regexp_match(split_part(tr.instrument,' ',1), '^([0-9A-Z]{4,6})'))[1])) AS code
      FROM public.trade_records tr
     WHERE tr.status = 'open'
       AND COALESCE(upper(tr.market),'TW') IN ('TW','TWSE','TPEX','')
       AND split_part(tr.instrument,' ',1) ~ '^[0-9]'
  ),
  trade_dates AS (
    SELECT td AS trade_date
      FROM public.tw_trading_days(_target_date - (_lookback_days - 1), _target_date) td
  ),
  expected AS (SELECT u.symbol, td.trade_date FROM uni u CROSS JOIN trade_dates td),
  existing AS (
    SELECT DISTINCT bd.stock_id, bd.trade_date
      FROM public.tw_bsr_daily bd
     WHERE bd.trade_date BETWEEN _target_date - (_lookback_days - 1) AND _target_date
  ),
  missing AS (
    SELECT e.symbol, e.trade_date
      FROM expected e
      LEFT JOIN existing ex ON ex.stock_id = e.symbol AND ex.trade_date = e.trade_date
      LEFT JOIN public.tw_bsr_sync_queue q
             ON q.stock_id = e.symbol AND q.trade_date = e.trade_date
            AND q.status IN ('pending','running')
     WHERE ex.stock_id IS NULL AND q.id IS NULL
  ),
  gaps AS (
    SELECT m.symbol, MIN(m.trade_date) AS min_date, MAX(m.trade_date) AS max_date, COUNT(*)::integer AS cnt
      FROM missing m GROUP BY m.symbol
  ),
  ranked AS (
    SELECT g.*,
           CASE
             WHEN 'checkup_storage' = ANY(u.sources) THEN 1
             WHEN 'trade_records' = ANY(u.sources) AND EXISTS (SELECT 1 FROM open_tr o WHERE o.code = g.symbol) THEN 2
             ELSE 3
           END AS source_rank
      FROM gaps g JOIN uni u ON u.symbol = g.symbol
  )
  SELECT r.symbol AS stock_id, r.min_date AS start_date, r.max_date AS end_date, r.cnt AS gap_count
    FROM ranked r
   ORDER BY r.source_rank ASC,
            (r.max_date = _target_date) DESC,
            r.cnt DESC,
            r.symbol ASC
   LIMIT _max_jobs;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.detect_fundamental_gap_jobs(_target_date date DEFAULT CURRENT_DATE, _max_jobs integer DEFAULT 1000)
 RETURNS TABLE(stock_id text, start_date date, end_date date, gap_count integer, missing_datasets text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH universe AS (
    SELECT DISTINCT (regexp_match(split_part(tr.instrument, ' ', 1), '^([1-9][0-9]{3})'))[1] AS symbol
    FROM public.trade_records tr
    WHERE tr.exit_date IS NULL
      AND COALESCE(upper(tr.market), 'TW') IN ('TW','TWSE','TPEX')
      AND split_part(tr.instrument, ' ', 1) ~ '^[1-9][0-9]{3}(\s|$)'
    UNION
    SELECT DISTINCT (regexp_match(split_part(es.instrument, ' ', 1), '^([1-9][0-9]{3})'))[1] AS symbol
    FROM public.expert_signals es
    WHERE es.published_at IS NOT NULL
      AND COALESCE(upper(es.market), 'TW') IN ('TW','TWSE','TPEX')
      AND split_part(es.instrument, ' ', 1) ~ '^[1-9][0-9]{3}(\s|$)'
  ),
  recent_months AS (
    SELECT generate_series(1, 12) AS i
  ),
  expected_monthly AS (
    SELECT u.symbol,
           DATE_TRUNC('month', _target_date - (rm.i || ' months')::interval)::date AS report_month
    FROM universe u
    CROSS JOIN recent_months rm
  ),
  existing_monthly AS (
    SELECT DISTINCT stock_id, DATE_TRUNC('month', report_date)::date AS report_month
    FROM public.stock_fundamentals
    WHERE dataset = 'monthly_revenue'
      AND report_date >= _target_date - interval '12 months'
  ),
  missing_monthly AS (
    SELECT em.symbol, em.report_month
    FROM expected_monthly em
    LEFT JOIN existing_monthly exm
      ON exm.stock_id = em.symbol AND exm.report_month = em.report_month
    WHERE exm.stock_id IS NULL
  ),
  recent_quarters AS (
    SELECT generate_series(1, 4) * 3 AS months_back
  ),
  expected_quarterly AS (
    SELECT u.symbol,
           DATE_TRUNC('quarter', _target_date - (rq.months_back || ' months')::interval)::date AS report_quarter
    FROM universe u
    CROSS JOIN recent_quarters rq
  ),
  existing_quarterly AS (
    SELECT DISTINCT stock_id, DATE_TRUNC('quarter', report_date)::date AS report_quarter
    FROM public.stock_fundamentals
    WHERE dataset IN ('financial_statements','balance_sheet','cash_flow')
      AND report_date >= _target_date - interval '12 months'
  ),
  missing_quarterly AS (
    SELECT eq.symbol, eq.report_quarter
    FROM expected_quarterly eq
    LEFT JOIN existing_quarterly exq
      ON exq.stock_id = eq.symbol AND exq.report_quarter = eq.report_quarter
    WHERE exq.stock_id IS NULL
  ),
  all_missing AS (
    SELECT symbol, report_month AS period, 'monthly_revenue'::TEXT AS missing_dataset
    FROM missing_monthly
    UNION ALL
    SELECT symbol, report_quarter, 'financial_statements'::TEXT
    FROM missing_quarterly
  ),
  grouped AS (
    SELECT symbol,
           MIN(period) AS min_period,
           MAX(period) AS max_period,
           COUNT(*)::INTEGER AS cnt,
           array_agg(DISTINCT missing_dataset) AS missing_datasets
    FROM all_missing
    GROUP BY symbol
  )
  SELECT symbol, min_period, max_period, cnt, missing_datasets
  FROM grouped
  ORDER BY cnt DESC
  LIMIT _max_jobs;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.detect_institutional_gap_jobs(_target_date date DEFAULT CURRENT_DATE, _lookback_days integer DEFAULT 60, _max_jobs integer DEFAULT 5000)
 RETURNS TABLE(stock_id text, start_date date, end_date date, gap_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH universe AS (
    SELECT u.code AS symbol FROM public.checkup_prefetch_universe() u WHERE u.supported
  ),
  trade_dates AS (
    SELECT td AS trade_date
      FROM public.tw_trading_days(_target_date - (_lookback_days - 1), _target_date) td
  ),
  expected AS (SELECT u.symbol, td.trade_date FROM universe u CROSS JOIN trade_dates td),
  existing AS (
    SELECT DISTINCT idl.stock_id, idl.trade_date
      FROM public.tw_institutional_daily idl
     WHERE idl.trade_date BETWEEN _target_date - (_lookback_days - 1) AND _target_date
  ),
  missing AS (
    SELECT e.symbol, e.trade_date
      FROM expected e
      LEFT JOIN existing ex ON ex.stock_id = e.symbol AND ex.trade_date = e.trade_date
     WHERE ex.stock_id IS NULL
  ),
  gaps AS (
    SELECT m.symbol, MIN(m.trade_date) AS min_date, MAX(m.trade_date) AS max_date, COUNT(*)::integer AS cnt
      FROM missing m GROUP BY m.symbol
  )
  SELECT g.symbol AS stock_id, g.min_date AS start_date, g.max_date AS end_date, g.cnt AS gap_count
    FROM gaps g ORDER BY g.cnt DESC LIMIT _max_jobs;
