DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enforce_plan_review_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  is_admin boolean;
  is_owner boolean;
BEGIN
  is_admin := has_role(auth.uid(), 'company_admin');

  -- Admins can change anything (including review_status / review_note / reviewed_by / reviewed_at)
  IF is_admin THEN
    -- Auto-fill reviewer metadata when status changes
    IF NEW.review_status IS DISTINCT FROM OLD.review_status THEN
      NEW.reviewed_by := auth.uid();
      NEW.reviewed_at := now();
    END IF;
    RETURN NEW;
  END IF;

  -- Check ownership
  SELECT EXISTS (
    SELECT 1 FROM public.experts
    WHERE id = NEW.expert_id AND user_id = auth.uid()
  ) INTO is_owner;

  IF is_owner THEN
    -- Block analyst from changing review fields directly
    NEW.review_status := 'pending';
    NEW.review_note := NULL;
    NEW.reviewed_by := NULL;
    NEW.reviewed_at := NULL;
  END IF;

  RETURN NEW;
END;
$function$
