DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enforce_unit_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing_unit    text;
  v_existing_source  text;
  v_existing_row_id  text;
  v_existing_symbol  text;
  v_existing_qty     numeric;
  v_existing_created timestamptz;
  v_asset_class      text;
  v_allowed          text[];
  v_allowed_str      text;
  v_symbol           text;
BEGIN
  IF NEW.quantity_unit IS NULL OR btrim(NEW.quantity_unit) = '' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.quantity_unit IS NOT NULL
     AND OLD.quantity_unit = NEW.quantity_unit
     AND OLD.instrument IS NOT DISTINCT FROM NEW.instrument
     AND OLD.expert_id IS NOT DISTINCT FROM NEW.expert_id THEN
    RETURN NEW;
  END IF;

  IF NEW.expert_id IS NULL OR NEW.instrument IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(asset_class, CASE WHEN currency = 'USD' THEN 'us_stock' ELSE 'tw_stock' END)
    INTO v_asset_class
  FROM public.experts
  WHERE id = NEW.expert_id;

  v_allowed := CASE COALESCE(v_asset_class, 'tw_stock')
    WHEN 'tw_stock'  THEN ARRAY['張','股']
    WHEN 'us_stock'  THEN ARRAY['股']
    WHEN 'crypto'    THEN ARRAY['顆']
    WHEN 'us_option' THEN ARRAY['口','組']
    WHEN 'us_future' THEN ARRAY['口']
    ELSE ARRAY['張','股']
  END;
  v_allowed_str := array_to_string(v_allowed, '/');

  IF NOT (NEW.quantity_unit = ANY(v_allowed)) THEN
    RAISE EXCEPTION
      '單位不相容：資產類別「%」不支援單位「%」，允許的單位為「%」。',
      COALESCE(v_asset_class, 'tw_stock'), NEW.quantity_unit, v_allowed_str
      USING ERRCODE = 'check_violation',
            HINT = 'ASSET_UNIT_LOCK: expert_id=' || NEW.expert_id::text
              || ', asset_class=' || COALESCE(v_asset_class, 'tw_stock')
              || ', attempted_unit=' || NEW.quantity_unit
              || ', allowed_units=' || v_allowed_str;
  END IF;

  -- 組合單（多腿）以「組」為部位單位，與單腿「口」互不衝突，跳過同標的混用檢查
  IF NEW.quantity_unit = '組' OR COALESCE(NEW.is_combo, false) THEN
    RETURN NEW;
  END IF;

  v_symbol := split_part(btrim(NEW.instrument), ' ', 1);

  SELECT quantity_unit, 'expert_signals', id::text,
         split_part(btrim(instrument), ' ', 1), quantity, created_at
    INTO v_existing_unit, v_existing_source, v_existing_row_id,
         v_existing_symbol, v_existing_qty, v_existing_created
  FROM public.expert_signals
  WHERE expert_id = NEW.expert_id
    AND split_part(btrim(instrument), ' ', 1) = v_symbol
    AND quantity_unit IS NOT NULL
    AND quantity_unit <> NEW.quantity_unit
    AND quantity_unit <> '組'
    AND COALESCE(is_combo, false) = false
    AND status = 'pending'
    AND (TG_TABLE_NAME <> 'expert_signals' OR id <> NEW.id)
  ORDER BY created_at ASC
  LIMIT 1;

  IF v_existing_unit IS NULL THEN
    SELECT quantity_unit, 'trade_records', id::text,
           split_part(btrim(instrument), ' ', 1), quantity, created_at
      INTO v_existing_unit, v_existing_source, v_existing_row_id,
           v_existing_symbol, v_existing_qty, v_existing_created
    FROM public.trade_records
    WHERE expert_id = NEW.expert_id
      AND split_part(btrim(instrument), ' ', 1) = v_symbol
      AND quantity_unit IS NOT NULL
      AND quantity_unit <> NEW.quantity_unit
      AND quantity_unit <> '組'
      AND COALESCE(is_combo, false) = false
      AND status = 'open'
      AND (TG_TABLE_NAME <> 'trade_records' OR id <> NEW.id)
    ORDER BY created_at ASC
    LIMIT 1;
  END IF;

  IF v_existing_unit IS NOT NULL THEN
    RAISE EXCEPTION
      '單位不一致：標的 % 目前已有一筆未平倉部位使用「%」單位（來源：% #%，數量 % %，建立於 %），無法在此代碼上同時混用「%」。允許單位：%。請先平倉，或到週記編輯頁使用「改單位…」把該部位單位校齊。',
      v_symbol,
      v_existing_unit,
      v_existing_source,
      v_existing_row_id,
      v_existing_qty,
      v_existing_unit,
      to_char(v_existing_created AT TIME ZONE 'Asia/Taipei', 'YYYY/MM/DD HH24:MI'),
      NEW.quantity_unit,
      v_allowed_str
      USING ERRCODE = 'check_violation',
            HINT = 'UNIT_LOCK: expert_id=' || NEW.expert_id::text
              || ', symbol=' || v_symbol
              || ', existing_source=' || v_existing_source
              || ', existing_row_id=' || v_existing_row_id
              || ', existing_unit=' || v_existing_unit
              || ', existing_quantity=' || COALESCE(v_existing_qty::text, '')
              || ', attempted_unit=' || NEW.quantity_unit
              || ', allowed_units=' || v_allowed_str
              || ', scope=open_positions_only';
  END IF;

  RETURN NEW;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enforce_user_performance_price()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_price numeric;
begin
  select cp.price
  into v_price
  from public.current_prices cp
  where cp.symbol = new.symbol
  limit 1;

  if v_price is null then
    new.current_price := null;
    new.pnl := null;
    new.pnl_percent := null;
  else
    new.current_price := v_price;

    if new.entry_price is not null and new.entry_price > 0 then
      new.pnl := round((v_price - new.entry_price)::numeric, 3);
      new.pnl_percent := round((((v_price - new.entry_price) / new.entry_price) * 100)::numeric, 2);
    else
      new.pnl := null;
      new.pnl_percent := null;
    end if;
  end if;

  return new;
end;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enqueue_all_active_tw_holdings_bsr(p_lookback_days integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'Asia/Taipei')::date;
  v_stock text;
  v_d date;
  v_days_added int;
  v_scanned int := 0;
  v_eligible int := 0;
  v_inserted int := 0;
  v_row_ct int;
BEGIN
  FOR v_stock, v_scanned IN
    SELECT u.code, 0 FROM public.checkup_prefetch_universe() u WHERE u.supported
  LOOP
    v_eligible := v_eligible + 1;
    v_d := v_today; v_days_added := 0;
    WHILE v_days_added < p_lookback_days LOOP
      IF EXTRACT(ISODOW FROM v_d) < 6 THEN
        INSERT INTO public.tw_bsr_sync_queue
          (stock_id, trade_date, priority, status, next_run_at, enqueued_by, correlation_id, post_close_only)
        VALUES (v_stock, v_d, CASE WHEN v_d = v_today THEN 1 ELSE 2 END,
                'pending', now(), 'enqueue_all_active_holdings', gen_random_uuid(), false)
        ON CONFLICT DO NOTHING;
        GET DIAGNOSTICS v_row_ct = ROW_COUNT;
        v_inserted := v_inserted + v_row_ct;
        v_days_added := v_days_added + 1;
      END IF;
      v_d := v_d - 1;
      EXIT WHEN v_d < v_today - 30;
    END LOOP;
  END LOOP;

  SELECT count(*) INTO v_scanned FROM public.checkup_prefetch_universe();

  RETURN jsonb_build_object(
    'stocks_scanned', v_scanned,
    'stocks_eligible', v_eligible,
    'inserted', v_inserted,
    'lookback_days', p_lookback_days
  );
END; $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enqueue_backfill_jobs(_jobs jsonb)
 RETURNS TABLE(inserted integer, skipped integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inserted INTEGER := 0;
  v_skipped INTEGER := 0;
  job RECORD;
BEGIN
  FOR job IN
    SELECT
      (j->>'dataset')::TEXT AS dataset,
      (j->>'stock_id')::TEXT AS stock_id,
      (j->>'start_date')::DATE AS start_date,
      (j->>'end_date')::DATE AS end_date,
      COALESCE((j->>'priority_score')::INTEGER, 0) AS priority_score,
      COALESCE((j->>'source_hint')::TEXT, 'finmind') AS source_hint,
      COALESCE((j->>'max_attempts')::INTEGER, 3) AS max_attempts,
      COALESCE(j->'payload', '{}'::JSONB) AS payload
    FROM jsonb_array_elements(_jobs) AS j
  LOOP
    INSERT INTO public.backfill_job_queue (
      dataset, stock_id, start_date, end_date, priority_score,
      source_hint, max_attempts, payload, status
    )
    VALUES (
      job.dataset, job.stock_id, job.start_date, job.end_date, job.priority_score,
      job.source_hint, job.max_attempts, job.payload, 'pending'
    )
    ON CONFLICT (dataset, stock_id, start_date, end_date, source_hint)
    WHERE status IN ('pending','running')
    DO NOTHING;

    IF FOUND THEN
      v_inserted := v_inserted + 1;
    ELSE
      v_skipped := v_skipped + 1;
    END IF;
  END LOOP;

  RETURN QUERY SELECT v_inserted, v_skipped;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enqueue_bsr_backfill(p_stock_id text, p_days integer DEFAULT 60)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_is_owner boolean := false;
  v_d date;
  v_inserted int := 0;
  v_count int := 0;
  v_row_ct int;
  v_max_days int := LEAST(GREATEST(p_days, 1), 120);
BEGIN
  IF p_stock_id IS NULL OR p_stock_id !~ '^[1-9][0-9]{3}$' THEN
    RAISE EXCEPTION 'invalid stock_id (must be 4-digit code starting 1-9)';
  END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT public.has_role(v_uid, 'company_admin') INTO v_is_admin;

  IF NOT v_is_admin THEN
    SELECT EXISTS (
      SELECT 1 FROM public.trade_records tr
      JOIN public.experts e ON e.id = tr.expert_id
      WHERE (regexp_match(COALESCE(tr.instrument, ''), '^([1-9][0-9]{3})(?:[[:space:]]|$)'))[1] = p_stock_id
        AND e.user_id = v_uid
    ) INTO v_is_owner;

    IF NOT v_is_owner THEN
      -- 只看「自己」的持倉列；解析 array 與 {holdings:[]} 兩種形狀
      SELECT EXISTS (
        SELECT 1
          FROM public.checkup_storage cs,
               LATERAL jsonb_array_elements(
                 CASE
                   WHEN jsonb_typeof(cs.data) = 'array' THEN cs.data
                   WHEN jsonb_typeof(cs.data->'holdings') = 'array' THEN cs.data->'holdings'
                   ELSE '[]'::jsonb
                 END
               ) h
         WHERE cs.user_id = v_uid
           AND cs.key LIKE 'pf-holdings%'
           AND upper(btrim(COALESCE(h->>'code', h->>'symbol'))) = p_stock_id
      ) INTO v_is_owner;
    END IF;

    IF NOT v_is_owner THEN
      RAISE EXCEPTION 'not authorized to backfill this stock';
    END IF;
  END IF;

  v_d := (now() AT TIME ZONE 'Asia/Taipei')::date;
  WHILE v_count < v_max_days LOOP
    IF EXTRACT(ISODOW FROM v_d) < 6 THEN
      INSERT INTO public.tw_bsr_sync_queue
        (stock_id, trade_date, priority, status, next_run_at, enqueued_by, correlation_id, post_close_only)
      VALUES (p_stock_id, v_d, 1, 'pending', now(), 'backfill_rpc', gen_random_uuid(), false)
      ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS v_row_ct = ROW_COUNT;
      v_inserted := v_inserted + v_row_ct;
      v_count := v_count + 1;
    END IF;
    v_d := v_d - 1;
    EXIT WHEN v_d < (now() AT TIME ZONE 'Asia/Taipei')::date - 200;
  END LOOP;

  RETURN v_inserted;
END; $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enqueue_bsr_first_fetch_on_trade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stock text;
  v_market text := UPPER(COALESCE(NEW.market, ''));
  v_d date;
  v_count int := 0;
BEGIN
  IF v_market NOT IN ('TW', 'TWSE', 'TPEX', '') THEN RETURN NEW; END IF;

  v_stock := (regexp_match(COALESCE(NEW.instrument, ''), '^([1-9][0-9]{3})(?:[[:space:]]|$)'))[1];
  IF v_stock IS NULL THEN RETURN NEW; END IF;

  IF (SELECT count(*) FROM public.tw_bsr_daily WHERE stock_id = v_stock) >= 20 THEN
    RETURN NEW;
  END IF;

  v_d := (now() AT TIME ZONE 'Asia/Taipei')::date;
  WHILE v_count < 60 LOOP
    IF EXTRACT(ISODOW FROM v_d) < 6 THEN
      INSERT INTO public.tw_bsr_sync_queue
        (stock_id, trade_date, priority, status, next_run_at, enqueued_by, correlation_id, post_close_only)
      VALUES
        (v_stock, v_d, 1, 'pending', now(), 'trade_insert_hook_backfill', gen_random_uuid(), false)
      ON CONFLICT DO NOTHING;
      v_count := v_count + 1;
    END IF;
    v_d := v_d - 1;
    EXIT WHEN v_d < (now() AT TIME ZONE 'Asia/Taipei')::date - 150;
  END LOOP;

  RETURN NEW;
END; $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enqueue_chips_prefetch_gaps(p_lookback_days integer DEFAULT 10, p_max_stocks integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tpe_now timestamp := (now() AT TIME ZONE 'Asia/Taipei');
  v_today date := v_tpe_now::date;
  v_end date;
  v_inserted int := 0;
  v_row_ct int;
  v_gaps int := 0;
  g record;
  d date;
  v_rank int;
  v_recover jsonb;
  v_bp jsonb;
  v_quota_recover jsonb;
BEGIN
  v_end := CASE WHEN v_tpe_now::time >= time '15:00' THEN v_today ELSE v_today - 1 END;
  SELECT max(td) INTO v_end FROM public.tw_trading_days(v_end - 10, v_end) td;
  IF v_end IS NULL THEN
    RETURN jsonb_build_object('skipped', 'no_trading_day');
  END IF;

  FOR g IN
    SELECT * FROM public.detect_chip_gap_jobs(v_end, p_lookback_days, p_max_stocks)
  LOOP
    v_gaps := v_gaps + 1;

    SELECT CASE
             WHEN 'checkup_storage' = ANY(u.sources) THEN 1
             WHEN 'trade_records' = ANY(u.sources) AND EXISTS (
               SELECT 1 FROM public.trade_records tr
                WHERE tr.status = 'open'
                  AND COALESCE(upper(tr.market),'TW') IN ('TW','TWSE','TPEX','')
                  AND upper(btrim((regexp_match(split_part(tr.instrument,' ',1), '^([0-9A-Z]{4,6})'))[1])) = g.stock_id
             ) THEN 2
             ELSE 3
           END
      INTO v_rank
      FROM public.checkup_prefetch_universe() u
     WHERE u.code = g.stock_id
     LIMIT 1;

    v_rank := COALESCE(v_rank, 3);

    FOR d IN
      SELECT td FROM public.tw_trading_days(v_end - (p_lookback_days - 1), v_end) td
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.tw_bsr_daily bd
         WHERE bd.stock_id = g.stock_id AND bd.trade_date = d
      ) THEN
        INSERT INTO public.tw_bsr_sync_queue
          (stock_id, trade_date, priority, status, next_run_at, enqueued_by, correlation_id, post_close_only)
        VALUES (g.stock_id, d, v_rank,
                'pending', now(), 'chips_prefetch_hourly:r' || v_rank, gen_random_uuid(), false)
        ON CONFLICT DO NOTHING;
        GET DIAGNOSTICS v_row_ct = ROW_COUNT;
        v_inserted := v_inserted + v_row_ct;
      END IF;
    END LOOP;
  END LOOP;

  v_recover := public.recover_stale_bsr_queue_jobs();

  v_bp := public.bsr_recovery_budget(12);
  v_quota_recover := public.recover_quota_failed_bsr_jobs((v_bp->>'budget')::int);

  RETURN jsonb_build_object(
    'target_date', v_end,
    'lookback_days', p_lookback_days,
    'stocks_with_gaps', v_gaps,
    'inserted', v_inserted,
    'recovery', v_recover,
    'backpressure', v_bp,
    'quota_recovery', v_quota_recover
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enqueue_institutional_backfill_universe()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _n INT;
BEGIN
  WITH cov AS (
    SELECT stock_id, COUNT(DISTINCT trade_date) AS d
      FROM public.tw_institutional_daily
     GROUP BY stock_id
  ),
  saved AS (
    SELECT DISTINCT upper(btrim(COALESCE(h->>'code', h->>'symbol'))) AS sid
      FROM public.checkup_storage cs,
           LATERAL jsonb_array_elements(
             CASE
               WHEN jsonb_typeof(cs.data) = 'array' THEN cs.data
               WHEN jsonb_typeof(cs.data->'holdings') = 'array' THEN cs.data->'holdings'
               ELSE '[]'::jsonb
             END
           ) h
     WHERE cs.key LIKE 'pf-holdings%'
  ),
  open_pos AS (
    SELECT DISTINCT sid FROM (
      SELECT SPLIT_PART(TRIM(tr.instrument), ' ', 1) AS sid
        FROM public.trade_records tr
       WHERE tr.market = 'TW' AND tr.status::text = 'open'
      UNION
      SELECT SPLIT_PART(TRIM(es.instrument), ' ', 1)
        FROM public.expert_signals es
       WHERE es.market = 'TW'
    ) x
  ),
  others AS (
    SELECT DISTINCT u.code AS sid
      FROM public.checkup_prefetch_universe() u
     WHERE u.supported
    UNION
    SELECT DISTINCT stock_id FROM public.v_active_tw_holdings
  ),
  r1 AS (SELECT sid FROM saved WHERE sid ~ '^[1-9][0-9]{3}$'),
  r2 AS (
    SELECT sid FROM open_pos
     WHERE sid ~ '^[1-9][0-9]{3}$'
       AND sid NOT IN (SELECT sid FROM r1)
  ),
  r3 AS (
    SELECT sid FROM others
     WHERE sid ~ '^[1-9][0-9]{3}$'
       AND sid NOT IN (SELECT sid FROM r1)
       AND sid NOT IN (SELECT sid FROM r2)
  ),
  elig AS (
    SELECT c.sid, c.rnk
      FROM (
        SELECT sid, 1 AS rnk FROM r1
        UNION ALL SELECT sid, 2 FROM r2
        UNION ALL SELECT sid, 3 FROM r3
      ) c
      LEFT JOIN cov ON cov.stock_id = c.sid
      LEFT JOIN public.institutional_new_stock_queue q ON q.stock_id = c.sid
     WHERE COALESCE(cov.d, 0) < 40
       AND (
         q.stock_id IS NULL
         OR (
           q.status IN ('failed', 'dead')
           AND q.attempts < 5
           AND q.next_attempt_at <= now()
           AND COALESCE(q.last_error, '') !~* '(no_data|delisted|ineligible|sealed|terminal)'
         )
       )
  ),
  cand AS (
        (SELECT sid FROM elig WHERE rnk = 1 ORDER BY sid LIMIT 20)
    UNION ALL
        (SELECT sid FROM elig WHERE rnk = 2 ORDER BY sid LIMIT 15)
    UNION ALL
        (SELECT sid FROM elig WHERE rnk = 3 ORDER BY sid LIMIT 5)
  ),
  ins AS (
    INSERT INTO public.institutional_new_stock_queue (stock_id, status, attempts, next_attempt_at)
    SELECT sid, 'pending', 0, now() FROM cand
    ON CONFLICT (stock_id) DO UPDATE
       SET status = 'pending',
           next_attempt_at = now() + LEAST(
             interval '24 hours',
             make_interval(mins => (30 * power(2, LEAST(public.institutional_new_stock_queue.attempts, 10)))::int)
           ),
           updated_at = now()
       WHERE public.institutional_new_stock_queue.status IN ('failed', 'dead')
         AND public.institutional_new_stock_queue.attempts < 5
         AND public.institutional_new_stock_queue.next_attempt_at <= now()
         AND COALESCE(public.institutional_new_stock_queue.last_error, '') !~* '(no_data|delisted|ineligible|sealed|terminal)'
    RETURNING 1
  )
  SELECT COUNT(*) INTO _n FROM ins;
  RETURN _n;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.enqueue_institutional_new_stock(_stock_id text)
 RETURNS TABLE(enqueued boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _cfg JSONB;
  _enabled BOOLEAN;
  _cap INT;
  _today_count INT;
  _existing RECORD;
BEGIN
  IF _stock_id IS NULL OR _stock_id !~ '^[1-9]\d{3}$' THEN
    RETURN QUERY SELECT false, 'invalid_stock_id'::text; RETURN;
  END IF;

  SELECT config INTO _cfg FROM public.tw_bsr_sync_config WHERE key = 'fastlane_enabled';
  _enabled := COALESCE((_cfg->>'enabled')::boolean, false);
  _cap := COALESCE((_cfg->>'daily_stock_cap')::int, 50);
  IF NOT _enabled THEN
    RETURN QUERY SELECT false, 'flag_disabled'::text; RETURN;
  END IF;

  SELECT id, status INTO _existing
    FROM public.institutional_new_stock_queue WHERE stock_id = _stock_id;
  IF FOUND AND _existing.status <> 'dead' THEN
    RETURN QUERY SELECT false, ('already_'||_existing.status)::text; RETURN;
  END IF;

  SELECT COUNT(*) INTO _today_count
    FROM public.institutional_new_stock_queue
   WHERE requested_at >= date_trunc('day', now() AT TIME ZONE 'Asia/Taipei') AT TIME ZONE 'Asia/Taipei';
  IF _today_count >= _cap THEN
    RETURN QUERY SELECT false, 'daily_cap_reached'::text; RETURN;
  END IF;

  INSERT INTO public.institutional_new_stock_queue (stock_id, status, attempts, next_attempt_at)
       VALUES (_stock_id, 'pending', 0, now())
  ON CONFLICT (stock_id) DO UPDATE
     SET status='pending', attempts=0, next_attempt_at=now(),
         last_error=NULL, updated_at=now();

  RETURN QUERY SELECT true, 'enqueued'::text;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.ensure_bsr_queued(p_stock_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_elig jsonb;
  v_today date;
  v_active record;
  v_done record;
  v_failure record;
  v_next timestamptz := now();
  v_reason text;
  v_inserted integer := 0;
  v_raw_rows integer := 0;
  v_done_threshold integer := 5;
  v_fake_done boolean := false;
BEGIN
  v_elig := public.tw_bsr_eligibility(p_stock_id);
  IF COALESCE((v_elig->>'eligible')::boolean, false) = false THEN
    RETURN v_elig || jsonb_build_object('created', false, 'status', 'ineligible');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('bsr_queue:' || p_stock_id));

  v_today := (now() AT TIME ZONE 'Asia/Taipei')::date;

  -- 已有 active job → no-op
  SELECT status, trade_date, next_run_at INTO v_active
    FROM public.tw_bsr_sync_queue
    WHERE stock_id = p_stock_id AND status IN ('pending','running')
    ORDER BY updated_at DESC
    LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'eligible', true,
      'created', false,
      'status', v_active.status,
      'trade_date', v_active.trade_date,
      'next_run_at', v_active.next_run_at
    );
  END IF;

  -- 今日已 done 必須同時有足夠 raw broker rows，否則視為 fake_done，允許重新排隊。
  SELECT trade_date, updated_at INTO v_done
    FROM public.tw_bsr_sync_queue
    WHERE stock_id = p_stock_id AND trade_date = v_today AND status = 'done'
    ORDER BY updated_at DESC
    LIMIT 1;
  IF FOUND THEN
    SELECT count(*) INTO v_raw_rows
      FROM public.tw_bsr_daily
      WHERE stock_id = p_stock_id AND trade_date = v_today;

    IF v_raw_rows >= v_done_threshold THEN
      RETURN jsonb_build_object(
        'eligible', true,
        'created', false,
        'status', 'completed',
        'trade_date', v_done.trade_date,
        'completed_at', v_done.updated_at,
        'raw_rows', v_raw_rows
      );
    END IF;

    v_fake_done := true;
  END IF;

  -- 尊重 fetch_failures 冷卻
  SELECT next_retry_at, reason INTO v_failure
    FROM public.tw_bsr_fetch_failures
    WHERE stock_id = p_stock_id AND resolved_at IS NULL
    ORDER BY trade_date DESC
    LIMIT 1;
  IF FOUND AND v_failure.next_retry_at IS NOT NULL AND v_failure.next_retry_at > now() THEN
    v_next := v_failure.next_retry_at;
    v_reason := v_failure.reason;
  END IF;

  INSERT INTO public.tw_bsr_sync_queue
    (stock_id, trade_date, priority, status, next_run_at, enqueued_by, correlation_id, post_close_only)
  VALUES
    (p_stock_id, v_today, 1, 'pending', v_next, 'ensure_bsr_queued', gen_random_uuid(), false)
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN jsonb_build_object(
    'eligible', true,
    'created', v_inserted > 0,
    'status', 'pending',
    'trade_date', v_today,
    'next_run_at', v_next,
    'respected_backoff_reason', v_reason,
    'requeued_fake_done', v_fake_done,
    'raw_rows', v_raw_rows,
    'required_raw_rows', v_done_threshold
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.ensure_bsr_window(p_stock_id text, p_window_days integer DEFAULT 5, p_horizon_days integer DEFAULT 14)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'Asia/Taipei')::date;
  v_valid_dates date[];
  v_existing text[] := ARRAY[]::text[];
  v_promoted text[] := ARRAY[]::text[];
  v_newly_queued text[] := ARRAY[]::text[];
  v_d date;
  v_added int := 0;
  v_target int;
  v_probe_exhausted boolean := null;
  v_existing_row record;
BEGIN
  IF p_stock_id !~ '^[1-9][0-9]{3}$' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_stock_id', 'stock_id', p_stock_id);
  END IF;

  IF NOT COALESCE((public.tw_bsr_eligibility(p_stock_id)->>'eligible')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'ineligible', 'stock_id', p_stock_id);
  END IF;

  SELECT COALESCE(exhausted, false) INTO v_probe_exhausted
    FROM public.tw_bsr_upstream_probe WHERE stock_id = p_stock_id;

  v_target := GREATEST(1, LEAST(60, p_window_days));

  SELECT COALESCE(array_agg(trade_date), ARRAY[]::date[])
    INTO v_valid_dates
    FROM (
      SELECT trade_date
        FROM public.tw_bsr_daily
       WHERE stock_id = p_stock_id
       GROUP BY trade_date
      HAVING COUNT(DISTINCT broker_id) >= 5
    ) x;

  v_d := v_today;
  WHILE v_added < v_target AND v_d > v_today - p_horizon_days LOOP
    IF EXTRACT(ISODOW FROM v_d) < 6 THEN
      IF v_d = ANY(v_valid_dates) THEN
        v_existing := array_append(v_existing, v_d::text);
        v_added := v_added + 1;
      ELSE
        SELECT id, status, priority
          INTO v_existing_row
          FROM public.tw_bsr_sync_queue
         WHERE stock_id = p_stock_id AND trade_date = v_d
         ORDER BY CASE status
                    WHEN 'done' THEN 4
                    WHEN 'running' THEN 1
                    WHEN 'pending' THEN 2
                    WHEN 'failed' THEN 3
                    WHEN 'skipped' THEN 3
                    ELSE 5 END, updated_at DESC
         LIMIT 1;

        IF v_existing_row.id IS NULL THEN
          BEGIN
            INSERT INTO public.tw_bsr_sync_queue
              (stock_id, trade_date, priority, status, next_run_at,
               enqueued_by, correlation_id, post_close_only)
            VALUES
              (p_stock_id, v_d, 1, 'pending', now(),
               'ensure_bsr_window', gen_random_uuid(), false);
            v_newly_queued := array_append(v_newly_queued, v_d::text);
            v_added := v_added + 1;
          EXCEPTION WHEN unique_violation THEN
            -- 併發競態：其他呼叫剛剛插入，視同已排程
            v_promoted := array_append(v_promoted, v_d::text);
            v_added := v_added + 1;
          END;
        ELSIF v_existing_row.status = 'done' THEN
          -- done 但沒有效資料 → 該日視為缺料，插入新一筆
          BEGIN
            INSERT INTO public.tw_bsr_sync_queue
              (stock_id, trade_date, priority, status, next_run_at,
               enqueued_by, correlation_id, post_close_only)
            VALUES
              (p_stock_id, v_d, 1, 'pending', now(),
               'ensure_bsr_window', gen_random_uuid(), false);
            v_newly_queued := array_append(v_newly_queued, v_d::text);
            v_added := v_added + 1;
          EXCEPTION WHEN unique_violation THEN
            v_promoted := array_append(v_promoted, v_d::text);
            v_added := v_added + 1;
          END;
        ELSE
          -- pending / running / failed / skipped → 提到最高優先、重排
          UPDATE public.tw_bsr_sync_queue
             SET priority = LEAST(priority, 1),
                 status = CASE WHEN status IN ('failed','skipped') THEN 'pending' ELSE status END,
                 next_run_at = LEAST(COALESCE(next_run_at, now()), now()),
                 updated_at = now()
           WHERE id = v_existing_row.id;
          v_promoted := array_append(v_promoted, v_d::text);
          v_added := v_added + 1;
        END IF;
      END IF;
    END IF;
    v_d := v_d - 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'stock_id', p_stock_id,
    'window_days', v_target,
    'today', v_today,
    'have_valid_days', array_length(v_valid_dates, 1),
    'existing_in_window', v_existing,
    'newly_queued', v_newly_queued,
    'promoted', v_promoted,
    'upstream_exhausted', COALESCE(v_probe_exhausted, false)
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.expected_latest_bsr_date()
 RETURNS date
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH base AS (
    SELECT CASE WHEN EXTRACT(hour FROM (now() AT TIME ZONE 'Asia/Taipei')) >= 15
                THEN (now() AT TIME ZONE 'Asia/Taipei')::date
                ELSE (now() AT TIME ZONE 'Asia/Taipei')::date - 1 END AS d
  ), cand AS (
    SELECT (SELECT d FROM base) - g AS dd FROM generate_series(0, 20) g
  )
  SELECT max(dd) FROM cand
   WHERE EXTRACT(ISODOW FROM dd) < 6
     AND NOT EXISTS (SELECT 1 FROM public.tw_market_holidays h WHERE h.trade_date = dd);
