DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.finmind_inflight_acquire(_key text, _stock_id text, _kind text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inserted boolean := false;
BEGIN
  -- GC expired first
  DELETE FROM public.finmind_inflight_requests WHERE expires_at < now();

  INSERT INTO public.finmind_inflight_requests(key, stock_id, kind)
    VALUES (_key, _stock_id, _kind)
    ON CONFLICT (key) DO NOTHING;
  GET DIAGNOSTICS inserted = ROW_COUNT;
  RETURN inserted;
END;
