DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_bsr_daily_series(_stock_id text, _days integer DEFAULT 60)
 RETURNS TABLE(trade_date date, concentration_ratio numeric, broker_count integer, low_quality boolean)
