DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_bsr_readiness_v2(_stock_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  valid_dates date[];
  exhausted boolean := false;
  oldest date;
  newest date;
  have int;
  low_q int;
  result jsonb := '{}'::jsonb;
  win int;
BEGIN
  SELECT ARRAY(
    SELECT as_of_date FROM public.tw_chips_rollup
     WHERE stock_id = _stock_id AND window_days = 5
       AND bsr_available = true AND COALESCE(broker_count, 0) >= 1
     ORDER BY as_of_date ASC
  ) INTO valid_dates;

  SELECT COALESCE(p.exhausted, false) INTO exhausted
    FROM public.tw_bsr_upstream_probe p
   WHERE p.stock_id = _stock_id;

  have := COALESCE(array_length(valid_dates, 1), 0);
  oldest := CASE WHEN have > 0 THEN valid_dates[1] END;
  newest := CASE WHEN have > 0 THEN valid_dates[have] END;

  SELECT COUNT(*) INTO low_q
    FROM public.tw_chips_rollup
   WHERE stock_id = _stock_id AND window_days = 5
     AND low_quality = true AND bsr_available = true;

  FOREACH win IN ARRAY ARRAY[5,20,60] LOOP
    result := result || jsonb_build_object(win::text, jsonb_build_object(
      'window_days', win,
      'have', have,
      'need', win,
      'state', CASE
        WHEN have = 0 AND exhausted THEN 'upstream_exhausted'
        WHEN have = 0 THEN 'no_data'
        WHEN have >= win THEN 'ready'
        WHEN exhausted THEN 'upstream_exhausted'
        ELSE 'filling'
      END,
      'oldest_available', oldest,
      'newest_available', newest,
      'low_quality_count', low_q
    ));
  END LOOP;

  RETURN result;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_coverage_stats(_scope text DEFAULT 'active_holdings'::text, _window_days integer DEFAULT 60)
 RETURNS TABLE(total_stocks integer, ready integer, filling integer, missing integer, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _cutoff DATE := (now() AT TIME ZONE 'Asia/Taipei')::date - _window_days;
BEGIN
  IF _scope <> 'active_holdings' THEN RAISE EXCEPTION 'unsupported scope: %', _scope; END IF;
  IF NOT public.has_role(auth.uid(), 'company_admin') THEN RAISE EXCEPTION 'admin only'; END IF;

  RETURN QUERY
  WITH stocks AS (SELECT stock_id FROM public.v_active_tw_holdings WHERE stock_id IS NOT NULL),
  coverage AS (
    SELECT s.stock_id,
           COUNT(DISTINCT tid.trade_date) FILTER (WHERE tid.trade_date >= _cutoff) AS days_covered
    FROM stocks s
    LEFT JOIN public.tw_institutional_daily tid ON tid.stock_id = s.stock_id
    GROUP BY s.stock_id
  )
  SELECT
    (SELECT COUNT(*)::int FROM stocks),
    COUNT(*) FILTER (WHERE days_covered >= LEAST(_window_days, 40))::int,
    COUNT(*) FILTER (WHERE days_covered > 0 AND days_covered < LEAST(_window_days, 40))::int,
    COUNT(*) FILTER (WHERE days_covered = 0)::int,
    now()
  FROM coverage;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_cron_job_runs(_jobnames text[] DEFAULT ARRAY['publish-weekly-journals-tw'::text, 'publish-weekly-journals-us'::text, 'publish-weekly-journals-watchdog'::text], _limit integer DEFAULT 100)
 RETURNS TABLE(jobname text, runid bigint, cron_status text, return_message text, start_time timestamp with time zone, end_time timestamp with time zone, sql_duration_ms integer, request_id bigint, http_status integer, http_error text, http_response_snippet text, http_duration_ms integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'net'
AS $function$
  WITH runs AS (
    SELECT j.jobname, d.runid, d.status AS cron_status, d.return_message,
           d.start_time, d.end_time,
           GREATEST(0, (EXTRACT(EPOCH FROM (d.end_time - d.start_time)) * 1000)::int) AS sql_duration_ms
    FROM cron.job_run_details d
    JOIN cron.job j ON j.jobid = d.jobid
    WHERE j.jobname = ANY(_jobnames)
    ORDER BY d.start_time DESC
    LIMIT _limit
  ),
  matched AS (
    SELECT r.*,
           (
             SELECT cdl.request_id
             FROM public.cron_dispatch_log cdl
             WHERE cdl.jobname = r.jobname
               AND cdl.dispatched_at >= r.start_time - interval '1 second'
               AND cdl.dispatched_at <= r.end_time + interval '2 seconds'
             ORDER BY cdl.dispatched_at ASC
             LIMIT 1
           ) AS request_id
    FROM runs r
  )
  SELECT m.jobname, m.runid, m.cron_status, m.return_message,
         m.start_time, m.end_time, m.sql_duration_ms,
         m.request_id,
         resp.status_code AS http_status,
         resp.error_msg AS http_error,
         LEFT(COALESCE(resp.content::text, ''), 400) AS http_response_snippet,
         CASE WHEN resp.created IS NOT NULL
              THEN GREATEST(0, (EXTRACT(EPOCH FROM (resp.created - m.start_time)) * 1000)::int)
              ELSE NULL END AS http_duration_ms
  FROM matched m
  LEFT JOIN net._http_response resp ON resp.id = m.request_id
  ORDER BY m.start_time DESC
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
