DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_event_heatmap(_from timestamp with time zone, _to timestamp with time zone)
 RETURNS TABLE(event_name text, total_count bigint, unique_visitors bigint, unique_users bigint, last_seen timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  RETURN QUERY
    SELECT
      e.event_name,
      COUNT(*)::bigint,
      COUNT(DISTINCT e.visitor_id)::bigint,
      COUNT(DISTINCT e.user_id)::bigint,
      MAX(e.occurred_at)
    FROM traffic_events e
    WHERE e.occurred_at >= _from AND e.occurred_at < _to
      AND e.event_name IS NOT NULL
      AND NOT e.is_internal
    GROUP BY e.event_name
    ORDER BY COUNT(*) DESC;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_expert_capital_status(_expert_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_starting numeric := 0;
  v_realized numeric := 0;
  v_open_cost numeric := 0;
  v_open_market numeric := 0;
  v_available numeric := 0;
  v_positions jsonb := '[]'::jsonb;
  v_recent jsonb := '[]'::jsonb;
  v_expert_currency text := 'TWD';
  v_expert_asset_class text := 'tw_stock';
BEGIN
  SELECT
    COALESCE(starting_capital, 0),
    COALESCE(NULLIF(currency, ''), 'TWD'),
    COALESCE(NULLIF(asset_class, ''), CASE WHEN currency = 'USD' THEN 'us_stock' ELSE 'tw_stock' END)
  INTO v_starting, v_expert_currency, v_expert_asset_class
  FROM public.experts
  WHERE id = _expert_id;

  SELECT COALESCE(SUM(
    COALESCE(quantity, 0) * (COALESCE(exit_price, entry_price, 0) - COALESCE(entry_price, 0))
  ), 0)
  INTO v_realized
  FROM public.trade_records
  WHERE expert_id = _expert_id
    AND status IN ('closed','stopped');

  SELECT COALESCE(SUM(COALESCE(quantity,0) * COALESCE(entry_price,0)), 0),
         COALESCE(SUM(COALESCE(quantity,0) * COALESCE(
           (SELECT price FROM public.current_prices cp
            WHERE cp.symbol = SPLIT_PART(tr.instrument, ' ', 1)
            LIMIT 1),
           tr.current_price, tr.entry_price, 0)), 0)
  INTO v_open_cost, v_open_market
  FROM public.trade_records tr
  WHERE expert_id = _expert_id AND status = 'open';

  v_available := v_starting + v_realized - v_open_cost;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', tr.id,
    'instrument', tr.instrument,
    'symbol', SPLIT_PART(tr.instrument, ' ', 1),
    'quantity_shares', tr.quantity,
    'quantity_unit', COALESCE(NULLIF(tr.quantity_unit, ''), CASE
      WHEN COALESCE(NULLIF(tr.currency, ''), v_expert_currency) = 'USD'
        AND v_expert_asset_class IN ('us_future', 'us_option') THEN '口'
      WHEN COALESCE(NULLIF(tr.currency, ''), v_expert_currency) = 'USD'
        AND v_expert_asset_class = 'crypto' THEN '顆'
      ELSE '股'
    END),
    'market', COALESCE(NULLIF(tr.market, ''), CASE WHEN COALESCE(NULLIF(tr.currency, ''), v_expert_currency) = 'USD' THEN 'US' ELSE 'TW' END),
    'currency', COALESCE(NULLIF(tr.currency, ''), v_expert_currency),
    'asset_class', CASE
      WHEN COALESCE(NULLIF(tr.currency, ''), v_expert_currency) = 'USD' THEN COALESCE(NULLIF(v_expert_asset_class, ''), 'us_stock')
      ELSE 'tw_stock'
    END,
    'entry_price', tr.entry_price,
    'entry_date', tr.entry_date,
    'current_price', COALESCE(cp.price, tr.current_price, tr.entry_price),
    'market_value', ROUND(COALESCE(tr.quantity,0) * COALESCE(cp.price, tr.current_price, tr.entry_price, 0), 0),
    'cost_value', ROUND(COALESCE(tr.quantity,0) * COALESCE(tr.entry_price,0), 0),
    'unrealized_pnl', ROUND(COALESCE(tr.quantity,0) * (COALESCE(cp.price, tr.current_price, tr.entry_price, 0) - COALESCE(tr.entry_price,0)), 0),
    'unrealized_pct', CASE WHEN COALESCE(tr.entry_price,0) > 0
      THEN ROUND(((COALESCE(cp.price, tr.current_price, tr.entry_price, 0) - tr.entry_price) / tr.entry_price) * 100, 2)
      ELSE 0 END
  ) ORDER BY tr.created_at DESC), '[]'::jsonb)
  INTO v_positions
  FROM public.trade_records tr
  LEFT JOIN public.current_prices cp ON cp.symbol = SPLIT_PART(tr.instrument, ' ', 1)
  WHERE tr.expert_id = _expert_id AND tr.status = 'open';

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', id,
    'instrument', instrument,
    'symbol', SPLIT_PART(instrument, ' ', 1),
    'status', status,
    'quantity_shares', quantity,
    'quantity_unit', COALESCE(NULLIF(quantity_unit, ''), CASE
      WHEN COALESCE(NULLIF(currency, ''), v_expert_currency) = 'USD'
        AND v_expert_asset_class IN ('us_future', 'us_option') THEN '口'
      WHEN COALESCE(NULLIF(currency, ''), v_expert_currency) = 'USD'
        AND v_expert_asset_class = 'crypto' THEN '顆'
      ELSE '股'
    END),
    'market', COALESCE(NULLIF(market, ''), CASE WHEN COALESCE(NULLIF(currency, ''), v_expert_currency) = 'USD' THEN 'US' ELSE 'TW' END),
    'currency', COALESCE(NULLIF(currency, ''), v_expert_currency),
    'asset_class', CASE
      WHEN COALESCE(NULLIF(currency, ''), v_expert_currency) = 'USD' THEN COALESCE(NULLIF(v_expert_asset_class, ''), 'us_stock')
      ELSE 'tw_stock'
    END,
    'entry_price', entry_price,
    'entry_date', entry_date,
    'exit_price', exit_price,
    'exit_date', exit_date,
    'pnl_percent', pnl_percent,
    'created_at', created_at
  ) ORDER BY created_at DESC), '[]'::jsonb)
  INTO v_recent
  FROM (
    SELECT * FROM public.trade_records
    WHERE expert_id = _expert_id
    ORDER BY created_at DESC
    LIMIT 20
  ) sub;

  RETURN jsonb_build_object(
    'starting_capital', ROUND(v_starting, 0),
    'realized_pnl_amount', ROUND(v_realized, 0),
    'open_cost_value', ROUND(v_open_cost, 0),
    'open_market_value', ROUND(v_open_market, 0),
    'unrealized_pnl_amount', ROUND(v_open_market - v_open_cost, 0),
    'available_cash', ROUND(v_available, 0),
    'currency', v_expert_currency,
    'asset_class', v_expert_asset_class,
    'open_positions', v_positions,
    'recent_trades', v_recent
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_expert_detail_bundle(_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  _uid uuid := auth.uid();
  _is_tester boolean := coalesce(public.is_tester(_uid), false);
  _expert record;
  _plans jsonb;
  _plan_ids uuid[];
  _mine jsonb;
  _count integer := 0;
begin
  select * into _expert
  from public.experts e
  where e.slug = _slug
    and (
      e.status = 'active'
      or (e.status = 'draft' and _is_tester)
    )
  limit 1;

  if not found then
    return null;
  end if;

  select
    coalesce(jsonb_agg(to_jsonb(p.*) order by p.price_monthly), '[]'::jsonb),
    coalesce(array_agg(p.id), array[]::uuid[])
  into _plans, _plan_ids
  from public.expert_plans p
  where p.expert_id = _expert.id
    and p.is_active = true
    and p.review_status = 'approved';

  if array_length(_plan_ids, 1) is null then
    _plan_ids := array[]::uuid[];
  end if;

  if array_length(_plan_ids, 1) > 0 then
    select count(*) into _count
    from public.member_subscriptions ms
    where ms.plan_id = any(_plan_ids)
      and ms.status = 'active';
  end if;

  if _uid is not null and array_length(_plan_ids, 1) > 0 then
    select coalesce(jsonb_agg(ms.plan_id), '[]'::jsonb) into _mine
    from public.member_subscriptions ms
    where ms.user_id = _uid
      and ms.status = 'active'
      and ms.plan_id = any(_plan_ids);
  else
    _mine := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'expert', to_jsonb(_expert),
    'plans', _plans,
    'my_subscribed_plan_ids', _mine,
    'subscriber_count', _count
  );
end;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_expert_revenue_breakdown(_from timestamp with time zone, _to timestamp with time zone)
 RETURNS TABLE(expert_id uuid, expert_name text, expert_slug text, orders bigint, gross numeric, net numeric, platform_amount numeric, expert_amount numeric, channel_reserve numeric, unique_buyers bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH base AS (
    SELECT rs.*, pt.user_id_from_sub AS user_id
    FROM public.revenue_splits rs
    LEFT JOIN LATERAL (
      SELECT ms.user_id AS user_id_from_sub
      FROM public.payment_transactions pt
      LEFT JOIN public.member_subscriptions ms ON ms.id = pt.subscription_id
      WHERE pt.id = rs.transaction_id
      LIMIT 1
    ) pt ON TRUE
    WHERE rs.created_at >= _from AND rs.created_at < _to
      AND rs.expert_id IS NOT NULL
  )
  SELECT
    b.expert_id,
    e.name,
    e.slug,
    COUNT(*)::bigint AS orders,
    COALESCE(SUM(b.gross),0)::numeric AS gross,
    COALESCE(SUM(b.net),0)::numeric AS net,
    COALESCE(SUM(b.platform_amount),0)::numeric AS platform_amount,
    COALESCE(SUM(b.expert_amount),0)::numeric AS expert_amount,
    COALESCE(SUM(b.channel_reserve),0)::numeric AS channel_reserve,
    COUNT(DISTINCT b.user_id)::bigint AS unique_buyers
  FROM base b
  LEFT JOIN public.experts e ON e.id = b.expert_id
  WHERE public.has_role(auth.uid(), 'company_admin'::app_role)
  GROUP BY b.expert_id, e.name, e.slug
  ORDER BY gross DESC;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_fastlane_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _out JSONB;
BEGIN
  IF NOT public.has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  SELECT jsonb_build_object(
    'config', (SELECT config FROM public.tw_bsr_sync_config WHERE key='fastlane_enabled'),
    'queue', (
      SELECT COALESCE(jsonb_object_agg(status, cnt), '{}'::jsonb) FROM (
        SELECT status, COUNT(*)::int cnt
          FROM public.institutional_new_stock_queue GROUP BY status
      ) s
    ),
    'today_enqueued', (
      SELECT COUNT(*)::int FROM public.institutional_new_stock_queue
       WHERE requested_at >= date_trunc('day', now() AT TIME ZONE 'Asia/Taipei') AT TIME ZONE 'Asia/Taipei'
    ),
    'recent_done', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'stock_id', stock_id, 'attempts', attempts, 'updated_at', updated_at
      ))
      FROM (
        SELECT stock_id, attempts, updated_at
          FROM public.institutional_new_stock_queue
         WHERE status='done' AND updated_at >= now() - interval '24 hours'
         ORDER BY updated_at DESC LIMIT 20
      ) d
    ), '[]'::jsonb),
    'recent_failed', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'stock_id', stock_id, 'attempts', attempts,
        'last_error', last_error, 'updated_at', updated_at
      ))
      FROM (
        SELECT stock_id, attempts, last_error, updated_at
          FROM public.institutional_new_stock_queue
         WHERE (status='dead' OR (status='pending' AND attempts > 0))
           AND last_error IS NOT NULL
           AND updated_at >= now() - interval '24 hours'
         ORDER BY updated_at DESC LIMIT 20
      ) f
    ), '[]'::jsonb)
  ) INTO _out;
  RETURN _out;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_funnel_overview(_from timestamp with time zone, _to timestamp with time zone, _steps text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s text;
  prev_visitors bigint := NULL;
  rows jsonb := '[]'::jsonb;
  cur bigint;
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  FOREACH s IN ARRAY _steps LOOP
    SELECT COUNT(DISTINCT visitor_id) INTO cur
    FROM traffic_events
    WHERE occurred_at >= _from AND occurred_at < _to
      AND event_name = s
      AND NOT is_internal;

    rows := rows || jsonb_build_array(jsonb_build_object(
      'step', s,
      'visitors', cur,
      'drop_from_prev', CASE WHEN prev_visitors IS NULL OR prev_visitors = 0 THEN NULL
                             ELSE ROUND(100.0 * (prev_visitors - cur) / prev_visitors, 1) END
    ));
    prev_visitors := cur;
  END LOOP;

  RETURN rows;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
