DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_owned_journal_bundle(_signal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_signal record;
  v_expert record;
  v_week jsonb;
  v_ws timestamptz;
  v_we timestamptz;
  v_is_admin boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT s.* INTO v_signal FROM public.expert_signals s WHERE s.id = _signal_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT e.* INTO v_expert FROM public.experts e WHERE e.id = v_signal.expert_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- 允許：本人擁有者 OR 平台管理員（company_admin / admin）預覽
  v_is_admin := public.has_role(v_uid, 'company_admin'::app_role)
             OR public.has_role(v_uid, 'admin'::app_role);
  IF v_expert.user_id <> v_uid AND NOT v_is_admin THEN
    RETURN NULL;
  END IF;

  v_ws := date_trunc('week', v_signal.published_at);
  v_we := v_ws + interval '4 days 23 hours 59 minutes 59 seconds';

  SELECT jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'instrument', s.instrument,
      'action', s.action,
      'price_hint', s.price_hint,
      'quantity', s.quantity,
      'quantity_unit', s.quantity_unit,
      'reason_summary', s.reason_summary,
      'reason_detail', s.reason_detail,
      'risk_notes', s.risk_notes,
      'learning_points', s.learning_points,
      'published_at', s.published_at,
      'expert_id', s.expert_id,
      'experts', jsonb_build_object(
        'name', v_expert.name,
        'slug', v_expert.slug,
        'role', v_expert.role,
        'avatar_url', v_expert.avatar_url,
        'currency', v_expert.currency
      )
    ) ORDER BY s.published_at DESC
  ) INTO v_week
  FROM public.expert_signals s
  WHERE s.expert_id = v_signal.expert_id
    AND s.status = 'published'
    AND s.published_at >= v_ws
    AND s.published_at <= v_we;

  RETURN jsonb_build_object(
    'signal', jsonb_build_object(
      'id', v_signal.id,
      'instrument', v_signal.instrument,
      'action', v_signal.action,
      'price_hint', v_signal.price_hint,
      'quantity', v_signal.quantity,
      'quantity_unit', v_signal.quantity_unit,
      'reason_summary', v_signal.reason_summary,
      'reason_detail', v_signal.reason_detail,
      'risk_notes', v_signal.risk_notes,
      'learning_points', v_signal.learning_points,
      'published_at', v_signal.published_at,
      'expert_id', v_signal.expert_id,
      'experts', jsonb_build_object(
        'name', v_expert.name,
        'slug', v_expert.slug,
        'role', v_expert.role,
        'avatar_url', v_expert.avatar_url,
        'currency', v_expert.currency
      )
    ),
    'weekSignals', COALESCE(v_week, '[]'::jsonb)
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_page_analytics(_from timestamp with time zone, _to timestamp with time zone, _include_internal boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(row_to_json(r) ORDER BY r.page_views DESC)
    FROM (
      SELECT
        route AS path,
        COUNT(*)::bigint AS page_views,
        COUNT(DISTINCT visitor_id)::bigint AS unique_visitors,
        COUNT(DISTINCT user_id) FILTER (WHERE user_id IS NOT NULL)::bigint AS logged_in_visitors
      FROM traffic_events
      WHERE occurred_at >= _from AND occurred_at < _to
        AND (_include_internal OR NOT is_internal)
      GROUP BY route
      ORDER BY COUNT(*) DESC
      LIMIT 100
    ) r
  ), '[]'::jsonb);
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_perf_metrics_summary(_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_since timestamptz := now() - (_days || ' days')::interval;
  v_daily jsonb;
  v_routes jsonb;
  v_totals jsonb;
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(d) ORDER BY d.day), '[]'::jsonb)
  INTO v_daily
  FROM (
    SELECT
      (date_trunc('day', created_at AT TIME ZONE 'Asia/Taipei'))::date AS day,
      COUNT(*) AS samples,
      ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY fcp_ms))::int AS fcp_p50,
      ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY fcp_ms))::int AS fcp_p95,
      ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY lcp_ms))::int AS lcp_p50,
      ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY lcp_ms))::int AS lcp_p95,
      ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY inp_ms))::int AS inp_p50,
      ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY inp_ms))::int AS inp_p95,
      ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY cls_score))::numeric(6,4) AS cls_p50,
      ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY cls_score))::numeric(6,4) AS cls_p95
    FROM public.perf_metrics
    WHERE created_at >= v_since
    GROUP BY 1
  ) d;

  SELECT COALESCE(jsonb_agg(row_to_json(r) ORDER BY r.samples DESC), '[]'::jsonb)
  INTO v_routes
  FROM (
    SELECT
      route,
      COUNT(*) AS samples,
      ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY fcp_ms))::int AS fcp_p50,
      ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY fcp_ms))::int AS fcp_p75,
      ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY fcp_ms))::int AS fcp_p95,
      ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY lcp_ms))::int AS lcp_p50,
      ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY lcp_ms))::int AS lcp_p95,
      ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY inp_ms))::int AS inp_p75,
      ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY inp_ms))::int AS inp_p95,
      ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY cls_score))::numeric(6,4) AS cls_p75
    FROM public.perf_metrics
    WHERE created_at >= v_since
    GROUP BY route
    LIMIT 200
  ) r;

  SELECT jsonb_build_object(
    'samples', COUNT(*),
    'routes', COUNT(DISTINCT route),
    'fcp_p50', ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY fcp_ms))::int,
    'fcp_p95', ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY fcp_ms))::int,
    'lcp_p50', ROUND(PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY lcp_ms))::int,
    'lcp_p95', ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY lcp_ms))::int,
    'inp_p75', ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY inp_ms))::int,
    'inp_p95', ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY inp_ms))::int,
    'cls_p75', ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY cls_score))::numeric(6,4),
    'cls_p95', ROUND(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY cls_score))::numeric(6,4)
  )
  INTO v_totals
  FROM public.perf_metrics
  WHERE created_at >= v_since;

  RETURN jsonb_build_object(
    'since', v_since,
    'totals', v_totals,
    'daily', v_daily,
    'routes', v_routes
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_plan_expert_status(p_plan_id uuid)
