DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_price_parity_summary(_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH scoped AS (
    SELECT * FROM public.price_parity_events
    WHERE created_at >= now() - make_interval(days => GREATEST(_days, 1))
      AND public.has_role(auth.uid(), 'company_admin')
  ),
  totals AS (
    SELECT
      count(*)::int AS events,
      count(DISTINCT symbol)::int AS symbols,
      round(avg(diff_pct)::numeric, 3) AS avg_diff_pct,
      round(max(diff_pct)::numeric, 3) AS max_diff_pct
    FROM scoped
  ),
  top AS (
    SELECT symbol, market,
           count(*)::int AS hits,
           round(avg(diff_pct)::numeric, 3) AS avg_diff_pct,
           round(max(diff_pct)::numeric, 3) AS max_diff_pct,
           max(created_at) AS last_seen
    FROM scoped
    GROUP BY symbol, market
    ORDER BY count(*) DESC, max(diff_pct) DESC
    LIMIT 20
  )
  SELECT jsonb_build_object(
    'totals', COALESCE((SELECT to_jsonb(t) FROM totals t), '{}'::jsonb),
    'top', COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM top x), '[]'::jsonb)
  );
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_pricing_bundle(_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_min_advisor int;
  v_min_mentor int;
  v_checkup_plans jsonb;
  v_quota jsonb := NULL;
BEGIN
  SELECT MIN(price_monthly) INTO v_min_advisor
  FROM public.expert_plans
  WHERE is_active = true
    AND plan_type::text LIKE 'analyst_%';

  SELECT MIN(price_monthly) INTO v_min_mentor
  FROM public.expert_plans
  WHERE is_active = true
    AND plan_type::text = 'mentor_weekly_journal';

  SELECT COALESCE(jsonb_agg(row_to_json(c) ORDER BY c.sort_order), '[]'::jsonb)
  INTO v_checkup_plans
  FROM (
    SELECT id, tier, name, description, price_monthly, price_yearly,
           monthly_quota, quota_period, features, sort_order
    FROM public.checkup_plans
    WHERE is_active = true
  ) c;

  IF _user_id IS NOT NULL THEN
    BEGIN
      v_quota := public.check_checkup_quota(_user_id);
    EXCEPTION WHEN OTHERS THEN
      v_quota := NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'min_advisor_price', v_min_advisor,
    'min_mentor_price', v_min_mentor,
    'checkup_plans', v_checkup_plans,
    'checkup_quota', v_quota
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_product_breakdown(_from timestamp with time zone, _to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  WITH classified AS (
    SELECT
      visitor_id,
      user_id,
      CASE
        WHEN route LIKE '/holding-checkup%' OR route LIKE '/portfolio%' OR route LIKE '/overview%'
          OR event_name LIKE 'checkup_%' THEN 'checkup'
        WHEN route LIKE '/app%' OR event_name IN ('signal_view','signal_card_click','holdings_dashboard_view','holding_card_click','journal_view','journal_card_click','app_dashboard_view') THEN 'signals'
        WHEN event_name IN ('learning_view','system_detail_view','learning_card_click') THEN 'learning'
        ELSE 'other'
      END AS product
    FROM traffic_events
    WHERE occurred_at >= _from AND occurred_at < _to AND NOT is_internal
  )
  SELECT jsonb_agg(row_to_json(r) ORDER BY r.events DESC)
  INTO v
  FROM (
    SELECT
      product,
      COUNT(*)::bigint AS events,
      COUNT(DISTINCT visitor_id)::bigint AS unique_visitors,
      COUNT(DISTINCT user_id) FILTER (WHERE user_id IS NOT NULL)::bigint AS logged_in_visitors
    FROM classified
    WHERE product <> 'other'
    GROUP BY product
  ) r;

  RETURN COALESCE(v, '[]'::jsonb);
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_public_experts_list()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.created_at), '[]'::jsonb)
  FROM (
    SELECT
      e.id, e.slug, e.name, e.role, e.avatar_url, e.bio, e.description,
      e.style_tags, e.markets, e.strategy_summary,
      e.backtest_1y_return, e.backtest_max_drawdown, e.backtest_annual_return,
      e.starting_capital, e.risk_preference, e.operation_cycle, e.strategy_name,
      e.status, e.created_at,
      COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', p.id,
          'plan_type', p.plan_type,
          'name', p.name,
          'description', p.description,
          'price_monthly', p.price_monthly,
          'price_yearly', p.price_yearly,
          'features', p.features,
          'is_active', p.is_active
        ) ORDER BY p.price_monthly)
        FROM public.expert_plans p
        WHERE p.expert_id = e.id
          AND p.is_active = true
          AND p.review_status = 'approved'
      ), '[]'::jsonb) AS expert_plans
    FROM public.experts e
    WHERE e.status = 'active'
  ) t;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_publish_batch_attempts(_limit integer DEFAULT 60)
 RETURNS TABLE(id uuid, market text, attempt_no integer, max_attempts integer, status text, scheduled_at timestamp with time zone, next_retry_at timestamp with time zone, started_at timestamp with time zone, finished_at timestamp with time zone, duration_ms integer, run_id text, parent_attempt_id uuid, root_attempt_id uuid, error_message text, response jsonb, trigger_source text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  RETURN QUERY
    SELECT
      a.id, a.market, a.attempt_no, a.max_attempts, a.status,
      a.scheduled_at, a.next_retry_at, a.started_at, a.finished_at,
      CASE WHEN a.started_at IS NOT NULL AND a.finished_at IS NOT NULL
           THEN (EXTRACT(EPOCH FROM (a.finished_at - a.started_at))*1000)::int
           ELSE NULL END AS duration_ms,
      a.run_id, a.parent_attempt_id, a.root_attempt_id,
      a.error_message, a.response, a.trigger_source, a.created_at
    FROM public.publish_batch_attempts a
    ORDER BY a.created_at DESC
    LIMIT LEAST(GREATEST(_limit,1), 500);
END; $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_publish_batch_runs(_limit integer DEFAULT 20)
 RETURNS TABLE(run_id text, started_at timestamp with time zone, ended_at timestamp with time zone, market text, pending_found integer, published integer, failed integer, pushed integer, push_fail integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(),'company_admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  WITH src AS (
    SELECT l.run_id, l.created_at, l.stage, l.msg
    FROM public.function_run_logs l
    WHERE l.fn='publish-weekly-journals'
      AND l.created_at >= now() - interval '14 days'
  ),
  runs AS (
    SELECT run_id,
           min(created_at) AS started_at,
           max(created_at) AS ended_at,
           max(CASE WHEN stage='filter_by_market' THEN split_part(msg,' ',3) END) AS market_raw,
           max(CASE WHEN stage='fetch_pending_signals'
                    THEN (regexp_matches(msg,'Found (\d+)'))[1]::int END) AS pending_found,
           max(CASE WHEN stage='mark_published'
                    THEN (regexp_matches(msg,'Published (\d+)/'))[1]::int END) AS published,
           max(CASE WHEN stage='mark_published'
                    THEN (regexp_matches(msg,'failed=(\d+)'))[1]::int END) AS failed,
           max(CASE WHEN stage='line_push'
                    THEN (regexp_matches(msg,'pushed=(\d+)'))[1]::int END) AS pushed,
           max(CASE WHEN stage='line_push'
                    THEN (regexp_matches(msg,'pushFail=(\d+)'))[1]::int END) AS push_fail
    FROM src
    GROUP BY run_id
  )
  SELECT r.run_id, r.started_at, r.ended_at,
         CASE WHEN r.market_raw ILIKE 'US%' THEN 'US'
              WHEN r.market_raw ILIKE 'TW%' THEN 'TW'
              ELSE 'ALL' END,
         COALESCE(r.pending_found,0),
         COALESCE(r.published,0),
         COALESCE(r.failed,0),
         COALESCE(r.pushed,0),
         COALESCE(r.push_fail,0)
  FROM runs r
  ORDER BY r.started_at DESC
  LIMIT _limit;
END $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_publish_batch_status()
 RETURNS TABLE(expert_id uuid, expert_name text, expert_slug text, market text, asset_class text, pending_count integer, published_this_week integer, failed_pending_count integer, last_attempt_at timestamp with time zone, last_error_kind text, last_error_msg text, last_error_signal_id uuid, last_run_id text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(),'company_admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  WITH us_classes AS (
    SELECT unnest(ARRAY['us_stock','us_futures','crypto']) AS c
  ),
  base AS (
    SELECT e.id, e.name, e.expert_slug, e.asset_class,
           CASE WHEN lower(e.asset_class) IN (SELECT c FROM us_classes)
                THEN 'US' ELSE 'TW' END AS mk
    FROM public.experts e
  ),
  sig_stats AS (
    SELECT s.expert_id,
           count(*) FILTER (WHERE s.status='pending')::int AS pending_count,
           count(*) FILTER (
             WHERE s.status='published'
               AND s.updated_at >= now() - interval '7 days'
           )::int AS published_this_week
    FROM public.expert_signals s
    WHERE s.updated_at >= now() - interval '14 days' OR s.status='pending'
    GROUP BY s.expert_id
  ),
  err_logs AS (
    SELECT l.expert_id, l.signal_id, l.msg, l.run_id, l.created_at,
           l.payload->>'kind' AS kind
    FROM public.function_run_logs l
    WHERE l.fn='publish-weekly-journals'
      AND l.stage='mark_published_iter'
      AND l.level='error'
      AND l.expert_id IS NOT NULL
      AND l.created_at >= now() - interval '14 days'
  ),
  latest_err AS (
    SELECT DISTINCT ON (expert_id)
           expert_id, created_at AS last_attempt_at, kind AS last_error_kind,
           msg AS last_error_msg, signal_id AS last_error_signal_id, run_id AS last_run_id
    FROM err_logs
    ORDER BY expert_id, created_at DESC
  ),
  failed_pending AS (
    SELECT el.expert_id, count(DISTINCT el.signal_id)::int AS cnt
    FROM err_logs el
    JOIN public.expert_signals s ON s.id = el.signal_id AND s.status='pending'
    GROUP BY el.expert_id
  )
  SELECT b.id, b.name, b.expert_slug, b.mk, b.asset_class,
         COALESCE(ss.pending_count,0),
         COALESCE(ss.published_this_week,0),
         COALESCE(fp.cnt,0),
         le.last_attempt_at, le.last_error_kind, le.last_error_msg,
         le.last_error_signal_id, le.last_run_id
  FROM base b
  LEFT JOIN sig_stats ss ON ss.expert_id = b.id
  LEFT JOIN latest_err le ON le.expert_id = b.id
  LEFT JOIN failed_pending fp ON fp.expert_id = b.id
  WHERE COALESCE(ss.pending_count,0) > 0
     OR COALESCE(ss.published_this_week,0) > 0
     OR le.last_attempt_at IS NOT NULL
  ORDER BY b.mk, b.name;
END $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_remittance_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  result jsonb;
BEGIN
  -- 未登入者一律看不到收款帳號
  IF uid IS NULL THEN
    RETURN NULL;
  END IF;

  -- 已登入會員皆可讀：
  -- 1) 結帳頁在建立訂單「之前」就要顯示收款帳號
  -- 2) 實際訂單狀態使用 awaiting_info，舊白名單未涵蓋，導致一律回 NULL
  SELECT value INTO result
  FROM public.payment_settings
  WHERE key = 'remittance_account';

  RETURN result;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_roas_ltv_by_campaign(_from timestamp with time zone, _to timestamp with time zone)
 RETURNS TABLE(utm_campaign text, utm_source text, utm_medium text, spend numeric, conversions_count bigint, unique_buyers bigint, gross_revenue numeric, first_arpu numeric, cac numeric, roas numeric, ltv_30d numeric, ltv_90d numeric, payback_ratio numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH conv AS (
    SELECT
      COALESCE(NULLIF(c.utm_campaign,''),'(none)') AS utm_campaign,
      COALESCE(NULLIF(c.utm_source,''),'(direct)') AS utm_source,
      COALESCE(NULLIF(c.utm_medium,''),'(none)') AS utm_medium,
      c.user_id,
      c.gross_amount::numeric AS gross_amount,
      c.occurred_at
    FROM public.conversions c
    WHERE c.occurred_at >= _from AND c.occurred_at < _to
  ),
  agg_conv AS (
    SELECT utm_campaign, utm_source, utm_medium,
           COUNT(*)::bigint AS conversions_count,
           COUNT(DISTINCT user_id)::bigint AS unique_buyers,
           COALESCE(SUM(gross_amount),0) AS gross_revenue
    FROM conv
    GROUP BY 1,2,3
  ),
  ltv AS (
    SELECT
      c.utm_campaign,
      SUM(CASE WHEN pt.created_at <= c.occurred_at + interval '30 days' THEN pt.amount ELSE 0 END)::numeric AS ltv_30d,
      SUM(CASE WHEN pt.created_at <= c.occurred_at + interval '90 days' THEN pt.amount ELSE 0 END)::numeric AS ltv_90d
    FROM conv c
    JOIN public.member_subscriptions ms ON ms.user_id = c.user_id
    JOIN public.payment_transactions pt ON pt.subscription_id = ms.id
    WHERE pt.created_at >= c.occurred_at
      AND pt.status::text IN ('succeeded','paid','success')
    GROUP BY 1
  ),
  spend AS (
    SELECT COALESCE(NULLIF(s.utm_campaign,''),'(none)') AS utm_campaign,
           SUM(s.spend_amount)::numeric AS spend
    FROM public.ad_spend s
    WHERE to_date(s.yyyymm,'YYYYMM') >= date_trunc('month', _from)
      AND to_date(s.yyyymm,'YYYYMM') <  date_trunc('month', _to) + interval '1 month'
    GROUP BY 1
  )
  SELECT
    a.utm_campaign,
    a.utm_source,
    a.utm_medium,
    COALESCE(sp.spend, 0) AS spend,
    a.conversions_count,
    a.unique_buyers,
    a.gross_revenue,
    CASE WHEN a.conversions_count > 0 THEN a.gross_revenue / a.conversions_count ELSE 0 END AS first_arpu,
    CASE WHEN a.unique_buyers > 0 AND COALESCE(sp.spend,0) > 0 THEN sp.spend / a.unique_buyers ELSE 0 END AS cac,
    CASE WHEN COALESCE(sp.spend,0) > 0 THEN a.gross_revenue / sp.spend ELSE 0 END AS roas,
    COALESCE(l.ltv_30d, 0) AS ltv_30d,
    COALESCE(l.ltv_90d, 0) AS ltv_90d,
    CASE WHEN COALESCE(sp.spend,0) > 0 THEN COALESCE(l.ltv_90d,0) / sp.spend ELSE 0 END AS payback_ratio
  FROM agg_conv a
  LEFT JOIN spend sp USING (utm_campaign)
  LEFT JOIN ltv l USING (utm_campaign)
  WHERE public.has_role(auth.uid(), 'company_admin'::app_role)
  ORDER BY a.gross_revenue DESC;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_top_instruments(_from timestamp with time zone, _to timestamp with time zone, _limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(row_to_json(r) ORDER BY r.events DESC)
    FROM (
      SELECT
        event_props->>'instrument' AS instrument,
        COUNT(*)::bigint AS events,
        COUNT(DISTINCT visitor_id)::bigint AS unique_visitors
      FROM traffic_events
      WHERE occurred_at >= _from AND occurred_at < _to
        AND event_props ? 'instrument'
        AND NOT is_internal
      GROUP BY event_props->>'instrument'
      ORDER BY COUNT(*) DESC
      LIMIT _limit
    ) r
  ), '[]'::jsonb);
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_traffic_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  visits_total bigint;
  events_total bigint;
  named_events_total bigint;
  last_visit timestamptz;
  last_event timestamptz;
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT count(*), max(last_seen_at) INTO visits_total, last_visit
    FROM public.traffic_visits;
  SELECT count(*), max(occurred_at) INTO events_total, last_event
    FROM public.traffic_events;
  SELECT count(*) INTO named_events_total
    FROM public.traffic_events WHERE event_name IS NOT NULL;

  RETURN jsonb_build_object(
    'visits_total', visits_total,
    'events_total', events_total,
    'named_events_total', named_events_total,
    'last_visit_at', last_visit,
    'last_event_at', last_event
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_traffic_overview(_from timestamp with time zone, _to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_kpi jsonb;
  v_daily jsonb;
  v_channels jsonb;
  v_campaigns jsonb;
  v_referrers jsonb;
  v_landings jsonb;
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  SELECT jsonb_build_object(
    'visitors', (SELECT COUNT(*) FROM traffic_visits WHERE first_seen_at >= _from AND first_seen_at < _to),
    'returning_visitors', (SELECT COUNT(*) FROM traffic_visits WHERE last_seen_at >= _from AND last_seen_at < _to AND first_seen_at < _from),
    'page_views', (SELECT COUNT(*) FROM traffic_events WHERE occurred_at >= _from AND occurred_at < _to),
    'signups', (SELECT COUNT(*) FROM traffic_visits WHERE user_id IS NOT NULL AND first_seen_at >= _from AND first_seen_at < _to),
    'orders', (SELECT COUNT(*) FROM conversions WHERE occurred_at >= _from AND occurred_at < _to),
    'gross', COALESCE((SELECT SUM(gross_amount) FROM conversions WHERE occurred_at >= _from AND occurred_at < _to), 0),
    'platform', COALESCE((SELECT SUM(platform_amount) FROM conversions WHERE occurred_at >= _from AND occurred_at < _to), 0)
  ) INTO v_kpi;

  SELECT COALESCE(jsonb_agg(row_to_json(d) ORDER BY d.day), '[]'::jsonb)
  INTO v_daily
  FROM (
    SELECT
      (date_trunc('day', g) AT TIME ZONE 'Asia/Taipei')::date AS day,
      (SELECT COUNT(*) FROM traffic_visits WHERE first_seen_at >= g AND first_seen_at < g + interval '1 day') AS visitors,
      (SELECT COUNT(*) FROM traffic_events WHERE occurred_at >= g AND occurred_at < g + interval '1 day') AS page_views,
      (SELECT COUNT(*) FROM conversions WHERE occurred_at >= g AND occurred_at < g + interval '1 day') AS orders,
      COALESCE((SELECT SUM(gross_amount) FROM conversions WHERE occurred_at >= g AND occurred_at < g + interval '1 day'), 0) AS gross
    FROM generate_series(date_trunc('day', _from), date_trunc('day', _to), interval '1 day') g
  ) d;

  SELECT COALESCE(jsonb_agg(row_to_json(c) ORDER BY c.visitors DESC), '[]'::jsonb)
  INTO v_channels
  FROM (
    SELECT
      channel,
      COUNT(*) AS visitors,
      (SELECT COUNT(*) FROM conversions co WHERE co.channel = tv.channel AND co.occurred_at >= _from AND co.occurred_at < _to) AS orders,
      (SELECT COALESCE(SUM(gross_amount),0) FROM conversions co WHERE co.channel = tv.channel AND co.occurred_at >= _from AND co.occurred_at < _to) AS gross
    FROM traffic_visits tv
    WHERE first_seen_at >= _from AND first_seen_at < _to
    GROUP BY channel
  ) c;

  SELECT COALESCE(jsonb_agg(row_to_json(c) ORDER BY c.gross DESC NULLS LAST, c.visitors DESC), '[]'::jsonb)
  INTO v_campaigns
  FROM (
    SELECT
      COALESCE(NULLIF(tv.utm_campaign,''), '(none)') AS campaign,
      COALESCE(NULLIF(tv.utm_source,''), '(direct)') AS source,
      COALESCE(NULLIF(tv.utm_medium,''), '(none)') AS medium,
      COUNT(*) AS visitors,
      COUNT(*) FILTER (WHERE tv.user_id IS NOT NULL) AS signups,
      (SELECT COUNT(*) FROM conversions co WHERE COALESCE(NULLIF(co.utm_campaign,''),'(none)') = COALESCE(NULLIF(tv.utm_campaign,''),'(none)') AND co.occurred_at >= _from AND co.occurred_at < _to) AS orders,
      (SELECT COALESCE(SUM(gross_amount),0) FROM conversions co WHERE COALESCE(NULLIF(co.utm_campaign,''),'(none)') = COALESCE(NULLIF(tv.utm_campaign,''),'(none)') AND co.occurred_at >= _from AND co.occurred_at < _to) AS gross
    FROM traffic_visits tv
    WHERE first_seen_at >= _from AND first_seen_at < _to
    GROUP BY 1, 2, 3
    LIMIT 100
  ) c;

  SELECT COALESCE(jsonb_agg(row_to_json(r) ORDER BY r.visitors DESC), '[]'::jsonb)
  INTO v_referrers
  FROM (
    SELECT COALESCE(NULLIF(first_referrer_host,''), '(direct)') AS host, COUNT(*) AS visitors
    FROM traffic_visits
    WHERE first_seen_at >= _from AND first_seen_at < _to
    GROUP BY 1
    ORDER BY visitors DESC
    LIMIT 20
  ) r;

  SELECT COALESCE(jsonb_agg(row_to_json(l) ORDER BY l.visitors DESC), '[]'::jsonb)
  INTO v_landings
  FROM (
    SELECT COALESCE(NULLIF(first_landing_path,''), '/') AS path, COUNT(*) AS visitors
    FROM traffic_visits
    WHERE first_seen_at >= _from AND first_seen_at < _to
    GROUP BY 1
    ORDER BY visitors DESC
    LIMIT 20
  ) l;

  RETURN jsonb_build_object(
    'kpi', v_kpi,
    'daily', v_daily,
    'channels', v_channels,
    'campaigns', v_campaigns,
    'referrers', v_referrers,
    'landings', v_landings
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_user_funnel_drop(_user_id uuid, _from timestamp with time zone, _to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_steps text[] := ARRAY['page_view','expert_view','plan_view','checkout_view','checkout_submit','checkout_success'];
  v_reached jsonb := '[]'::jsonb;
  s text;
  hit boolean;
  last_reached text;
  dropped_at text;
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  FOREACH s IN ARRAY v_steps LOOP
    SELECT EXISTS (
      SELECT 1 FROM public.traffic_events
      WHERE user_id = _user_id
        AND event_name = s
        AND occurred_at >= _from AND occurred_at < _to
    ) INTO hit;
    v_reached := v_reached || jsonb_build_array(jsonb_build_object('step', s, 'reached', hit));
    IF hit THEN last_reached := s; ELSIF last_reached IS NOT NULL AND dropped_at IS NULL THEN dropped_at := s; END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'steps', v_reached,
    'last_reached', last_reached,
    'dropped_at', dropped_at
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_user_journey(_visitor_id text, _from timestamp with time zone, _to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(row_to_json(r) ORDER BY r.occurred_at)
    FROM (
      SELECT occurred_at, route, event_name, event_props, is_internal
      FROM traffic_events
      WHERE visitor_id = _visitor_id
        AND occurred_at >= _from AND occurred_at < _to
      ORDER BY occurred_at
      LIMIT 500
    ) r
  ), '[]'::jsonb);
END;
