DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_user_subscription_timeline(_user_id uuid, _expert_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;
  IF v_caller <> _user_id AND NOT public.has_role(v_caller, 'company_admin') THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(row_to_json(t) ORDER BY t.expert_name)
    FROM (
      SELECT
        e.id AS expert_id,
        e.name AS expert_name,
        e.slug AS expert_slug,
        e.avatar_url AS expert_avatar_url,
        e.role AS expert_role,
        EXISTS (
          SELECT 1
          FROM public.member_subscriptions ms2
          JOIN public.expert_plans ep2 ON ep2.id = ms2.plan_id
          WHERE ms2.user_id = _user_id
            AND ep2.expert_id = e.id
            AND ms2.status = 'active'
            AND (ms2.expires_at IS NULL OR ms2.expires_at > now())
        ) AS has_active_now,
        (
          SELECT jsonb_agg(jsonb_build_object(
            'id', ms.id,
            'plan_name', ep.name,
            'started_at', ms.started_at,
            'expires_at', ms.expires_at,
            'status', ms.status,
            'canceled_at', ms.canceled_at,
            'is_currently_active', (ms.status = 'active' AND (ms.expires_at IS NULL OR ms.expires_at > now()))
          ) ORDER BY ms.started_at)
          FROM public.member_subscriptions ms
          JOIN public.expert_plans ep ON ep.id = ms.plan_id
          WHERE ms.user_id = _user_id
            AND ep.expert_id = e.id
        ) AS segments
      FROM public.experts e
      WHERE e.role = 'mentor'
        AND (_expert_id IS NULL OR e.id = _expert_id)
        AND EXISTS (
          SELECT 1
          FROM public.member_subscriptions ms
          JOIN public.expert_plans ep ON ep.id = ms.plan_id
          WHERE ms.user_id = _user_id
            AND ep.expert_id = e.id
        )
    ) t
  ), '[]'::jsonb);
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.get_weekly_limit_up_leaderboard(_start_date date DEFAULT (date_trunc('week'::text, (now() AT TIME ZONE 'Asia/Taipei'::text)))::date, _end_date date DEFAULT ((now() AT TIME ZONE 'Asia/Taipei'::text))::date)
 RETURNS TABLE(expert_id uuid, expert_name text, expert_slug text, avatar_url text, limit_up_count bigint, win_rate numeric, weekly_return numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH hits AS (
    SELECT h.expert_id, COUNT(*) AS cnt
    FROM expert_limit_up_hits h
    WHERE h.trade_date BETWEEN _start_date AND _end_date
    GROUP BY h.expert_id
  ),
  perf AS (
    SELECT tr.expert_id,
      COUNT(*) FILTER (WHERE tr.status IN ('closed','stopped')) AS total_closed,
      COUNT(*) FILTER (WHERE tr.status IN ('closed','stopped') AND tr.pnl_percent > 0) AS wins,
      COALESCE(SUM(tr.pnl_percent) FILTER (WHERE tr.status IN ('closed','stopped') AND tr.exit_date >= _start_date::timestamptz), 0) AS week_ret
    FROM trade_records tr
    WHERE tr.expert_id IN (SELECT expert_id FROM hits)
    GROUP BY tr.expert_id
  )
  SELECT
    e.id AS expert_id,
    e.name AS expert_name,
    e.slug AS expert_slug,
    e.avatar_url,
    COALESCE(h.cnt, 0) AS limit_up_count,
    CASE WHEN COALESCE(p.total_closed, 0) > 0
      THEN ROUND((p.wins::numeric / p.total_closed) * 100, 1)
      ELSE 0
    END AS win_rate,
    ROUND(COALESCE(p.week_ret, 0), 1) AS weekly_return
  FROM hits h
  JOIN experts e ON e.id = h.expert_id AND e.status = 'active'
  LEFT JOIN perf p ON p.expert_id = h.expert_id
  ORDER BY h.cnt DESC, weekly_return DESC
  LIMIT 10;
$function$
