DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.is_tw_trading_day(_d date)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
