DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.normalize_snapshot_volume_shares(p_market text, p_volume bigint, p_hint_unit text DEFAULT NULL::text)
 RETURNS TABLE(unit text, shares bigint)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_unit TEXT;
  v_shares BIGINT;
BEGIN
  IF p_volume IS NULL THEN
    RETURN QUERY SELECT 'unknown'::TEXT, NULL::BIGINT;
    RETURN;
  END IF;

  IF p_hint_unit IN ('lots', 'shares', 'contracts') THEN
    v_unit := p_hint_unit;
  ELSIF p_market = 'TW' THEN
    v_unit := CASE WHEN p_volume < 10000000 THEN 'lots' ELSE 'shares' END;
  ELSIF p_market IN ('US', 'CRYPTO') THEN
    v_unit := 'shares';
  ELSE
    v_unit := 'unknown';
  END IF;

  v_shares := CASE WHEN v_unit = 'lots' THEN p_volume * 1000 ELSE p_volume END;
  RETURN QUERY SELECT v_unit, v_shares;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.notify_subscribers_on_announcement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (
    TG_OP = 'INSERT' AND NEW.status = 'published'
  ) OR (
    TG_OP = 'UPDATE' AND NEW.status = 'published' AND COALESCE(OLD.status::text, '') <> 'published'
  ) THEN
    INSERT INTO public.notifications (user_id, title, body, type, link)
    SELECT DISTINCT recipients.user_id,
           '📢 系統公告',
           NEW.title,
           'info',
           NULL
    FROM (
      SELECT p.user_id
      FROM public.profiles p
      WHERE p.user_id IS NOT NULL

      UNION

      SELECT e.user_id
      FROM public.experts e
      WHERE e.user_id IS NOT NULL

      UNION

      SELECT ms.user_id
      FROM public.member_subscriptions ms
      WHERE ms.user_id IS NOT NULL
    ) AS recipients;
  END IF;

  RETURN NEW;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.perf_metrics_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  recent_count integer;
BEGIN
  -- 1) session_id 維度：60 秒內同 session 最多 20 筆
  IF NEW.session_id IS NOT NULL THEN
    SELECT count(*) INTO recent_count
    FROM public.perf_metrics
    WHERE session_id = NEW.session_id
      AND created_at > now() - interval '60 seconds';
    IF recent_count >= 20 THEN
      RETURN NULL; -- 靜默丟棄，不噴錯
    END IF;
  END IF;

  -- 2) user_id 維度：60 秒內同 user 最多 60 筆
  IF NEW.user_id IS NOT NULL THEN
    SELECT count(*) INTO recent_count
    FROM public.perf_metrics
    WHERE user_id = NEW.user_id
      AND created_at > now() - interval '60 seconds';
    IF recent_count >= 60 THEN
      RETURN NULL;
    END IF;
  END IF;

  -- 3) 完全匿名 (無 session_id、無 user_id)：60 秒內同 route 全域最多 100 筆
  IF NEW.session_id IS NULL AND NEW.user_id IS NULL THEN
    SELECT count(*) INTO recent_count
    FROM public.perf_metrics
    WHERE route = NEW.route
      AND session_id IS NULL
      AND user_id IS NULL
      AND created_at > now() - interval '60 seconds';
    IF recent_count >= 100 THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.price_admit(p_market text, p_requested integer, p_writer text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pool         public.price_quota_pools%ROWTYPE;
  v_now          timestamptz := now();
  v_elapsed_s    double precision;
  v_refill_rate  double precision;
  v_new_tokens   double precision;
  v_admit        integer;
BEGIN
  SELECT * INTO v_pool FROM public.price_quota_pools WHERE market = p_market FOR UPDATE;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_elapsed_s := EXTRACT(EPOCH FROM (v_now - v_pool.last_refill));
  v_refill_rate := v_pool.per_min_cap::double precision / 60.0;  -- tokens per second
  v_new_tokens := LEAST(v_pool.per_min_cap::double precision,
                        v_pool.tokens + v_elapsed_s * v_refill_rate);

  v_admit := LEAST(p_requested, FLOOR(v_new_tokens)::integer);
  IF v_admit < 0 THEN v_admit := 0; END IF;

  UPDATE public.price_quota_pools
    SET tokens = v_new_tokens - v_admit,
        last_refill = v_now,
        updated_at = v_now
    WHERE market = p_market;

  INSERT INTO public.price_quota_ledger (market, requested, admitted, tokens_after, writer)
    VALUES (p_market, p_requested, v_admit, v_new_tokens - v_admit, p_writer);

  RETURN v_admit;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
