DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.purge_expired_bsr_reservations(_api text DEFAULT 'finmind'::text)
 RETURNS TABLE(recycled_count integer, recycled_ids bigint[])
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE _ids bigint[];
BEGIN
  WITH r AS (
    UPDATE public.tw_bsr_api_reservations
       SET released = true,
           settled_at = now(),
           recycle_reason = COALESCE(recycle_reason, 'expired_lease')
     WHERE api_name = _api
       AND settled_at IS NULL
       AND released = false
       AND expires_at < now()
     RETURNING id
  )
  SELECT COALESCE(array_agg(id), ARRAY[]::bigint[]) INTO _ids FROM r;

  DELETE FROM public.tw_bsr_api_reservations
   WHERE reserved_at < now() - interval '24 hours';

  RETURN QUERY SELECT COALESCE(array_length(_ids, 1), 0), _ids;
END;
