DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.rebuild_bsr_rollup(_as_of date, _stock_ids text[] DEFAULT NULL::text[], _max_stocks integer DEFAULT 400)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sid text; v_rows int := 0; v_stocks int := 0;
  v_dates date[]; v_win int; v_use date[]; v_src date;
  v_top_buy jsonb; v_top_sell jsonb; v_conc numeric; v_broker_count int;
BEGIN
  FOR v_sid IN
    SELECT DISTINCT stock_id FROM public.tw_bsr_daily
     WHERE trade_date = _as_of
       AND (_stock_ids IS NULL OR stock_id = ANY(_stock_ids))
     ORDER BY stock_id
     LIMIT _max_stocks
  LOOP
    v_stocks := v_stocks + 1;
    SELECT array_agg(d ORDER BY d DESC) INTO v_dates
      FROM (SELECT DISTINCT trade_date d FROM public.tw_bsr_daily
             WHERE stock_id = v_sid AND trade_date <= _as_of
               AND trade_date >= _as_of - 90) t;
    IF v_dates IS NULL THEN CONTINUE; END IF;

    SELECT COUNT(DISTINCT broker_id) INTO v_broker_count
      FROM public.tw_bsr_daily WHERE stock_id = v_sid AND trade_date = _as_of;

    FOREACH v_win IN ARRAY ARRAY[1,5,10,20,60] LOOP
      v_use := v_dates[1:LEAST(v_win, array_length(v_dates,1))];
      v_src := v_use[1];

      WITH agg AS (
        SELECT broker_id,
               COALESCE(MAX(NULLIF(TRIM(broker_name),'')), '券商分點 ' || broker_id) AS nm,
               SUM(COALESCE(net_shares,0))::bigint AS net,
               SUM(COALESCE(buy_shares,0))::bigint AS buy
          FROM public.tw_bsr_daily
         WHERE stock_id = v_sid AND trade_date = ANY(v_use)
         GROUP BY broker_id
      )
      SELECT
        (SELECT jsonb_agg(jsonb_build_object('broker_id',broker_id,'name',nm,'net',net))
           FROM (SELECT * FROM agg ORDER BY net DESC LIMIT 3) x),
        (SELECT jsonb_agg(jsonb_build_object('broker_id',broker_id,'name',nm,'net',net))
           FROM (SELECT * FROM agg ORDER BY net ASC LIMIT 3) y),
        CASE WHEN (SELECT SUM(buy) FROM agg) > 0
             THEN ROUND((SELECT SUM(buy) FROM (SELECT buy FROM agg ORDER BY buy DESC LIMIT 15) z)::numeric
                        / (SELECT SUM(buy) FROM agg)::numeric * 100, 2)
             ELSE NULL END
      INTO v_top_buy, v_top_sell, v_conc;

      IF v_top_buy IS NULL THEN CONTINUE; END IF;

      INSERT INTO public.tw_chips_rollup
        (stock_id, as_of_date, window_days, source_date, fallback_used,
         foreign_net, trust_net, dealer_net, top_buy_brokers, top_sell_brokers,
         concentration_ratio, bsr_available, broker_count, low_quality, updated_at)
      VALUES (v_sid, _as_of, v_win, v_src, v_src < _as_of,
              0, 0, 0, v_top_buy, v_top_sell,
              v_conc, true,
              CASE WHEN v_win = 5 THEN v_broker_count ELSE NULL END,
              CASE WHEN v_win = 5 THEN (v_broker_count > 0 AND v_broker_count < 5) ELSE NULL END,
              now())
      ON CONFLICT (stock_id, as_of_date, window_days) DO UPDATE
        SET source_date = EXCLUDED.source_date,
            fallback_used = EXCLUDED.fallback_used,
            top_buy_brokers = EXCLUDED.top_buy_brokers,
            top_sell_brokers = EXCLUDED.top_sell_brokers,
            concentration_ratio = EXCLUDED.concentration_ratio,
            bsr_available = true,
            broker_count = COALESCE(EXCLUDED.broker_count, public.tw_chips_rollup.broker_count),
            low_quality = COALESCE(EXCLUDED.low_quality, public.tw_chips_rollup.low_quality),
            updated_at = now();
      v_rows := v_rows + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('as_of', _as_of, 'stocks', v_stocks, 'rows', v_rows);
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.recalc_user_summary_on_perf_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _remaining int;
  _total double precision;
  _avg double precision;
BEGIN
  SELECT count(*), coalesce(sum(pnl_percent), 0), coalesce(avg(pnl_percent), 0)
    INTO _remaining, _total, _avg
    FROM user_performances
   WHERE user_id = OLD.user_id;

  IF _remaining = 0 THEN
    UPDATE user_summaries
       SET total_pnl_percent = 0,
           avg_pnl_percent = 0,
           updated_at = now()
     WHERE user_id = OLD.user_id;
  ELSE
    UPDATE user_summaries
       SET total_pnl_percent = _total,
           avg_pnl_percent = _avg,
           updated_at = now()
     WHERE user_id = OLD.user_id;
  END IF;

  RETURN OLD;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.reconcile_line_free_quota(_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text;
  v_is_line boolean := false;
  v_usage_count int := 0;
  v_has_history boolean := false;
  v_refunded int := 0;
  v_reason text := 'skipped';
BEGIN
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED';
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = _user_id LIMIT 1;
  v_is_line := v_email IS NOT NULL AND v_email LIKE 'line_%@line.local';

  IF NOT v_is_line THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'not_line_user', 'refunded_count', 0);
  END IF;

  SELECT count(*)::int INTO v_usage_count
    FROM public.checkup_usage
   WHERE user_id = _user_id
     AND kind = 'daily-analysis';

  IF v_usage_count = 0 THEN
    RETURN jsonb_build_object('reconciled', false, 'reason', 'no_usage', 'refunded_count', 0);
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.checkup_storage
     WHERE user_id = _user_id
       AND key = 'pf-analysis-history-v1'
       AND jsonb_typeof(data) = 'array'
       AND jsonb_array_length(data) > 0
  ) INTO v_has_history;

  IF v_has_history THEN
    v_reason := 'usage_matches_storage';
  ELSE
    WITH del AS (
      DELETE FROM public.checkup_usage
       WHERE user_id = _user_id
         AND kind = 'daily-analysis'
       RETURNING 1
    )
    SELECT count(*)::int INTO v_refunded FROM del;
    v_reason := 'refunded_no_storage';

    INSERT INTO public.audit_logs (actor_id, action, target_type, target_id, detail)
    VALUES (
      NULL,
      'checkup_quota.reconcile_refund',
      'profile',
      _user_id,
      jsonb_build_object('refunded_count', v_refunded, 'at', now())
    );
  END IF;

  RETURN jsonb_build_object(
    'reconciled', v_refunded > 0,
    'reason', v_reason,
    'refunded_count', v_refunded,
    'usage_before', v_usage_count,
    'has_history', v_has_history
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.reconcile_snapshot(_trade_date date)
 RETURNS TABLE(trade_date date, lane_a_status text, lane_b_status text, lane_c_status text, sealed_at timestamp with time zone, sealed_by_lane text, coverage_stocks integer, coverage_brokers integer, bsr_stocks integer, inst_stocks integer, notes text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_bsr_min_stocks constant int := 500;
  v_bsr_min_brokers_per_stock constant int := 5;
  v_inst_min_stocks constant int := 800;

  v_bsr_stocks int := 0;
  v_bsr_broker_rows int := 0;
  v_bsr_stocks_with_min int := 0;

  v_inst_stocks int := 0;
  v_inst_twse int := 0;
  v_inst_tpex int := 0;
  v_inst_t86 int := 0;

  v_lane_a text := 'pending';
  v_lane_b text := 'pending';
  v_lane_c text := 'pending';
  v_sealed_at timestamptz := NULL;
  v_sealed_by_lane text := NULL;
  v_notes text := '';
BEGIN
  -- ---- Lane A: BSR coverage ----
  SELECT
    count(DISTINCT d.stock_id),
    count(*),
    count(DISTINCT d.stock_id) FILTER (
      WHERE d.stock_id IN (
        SELECT d2.stock_id FROM public.tw_bsr_daily d2
        WHERE d2.trade_date = _trade_date
        GROUP BY d2.stock_id
        HAVING count(DISTINCT d2.broker_id) >= v_bsr_min_brokers_per_stock
      )
    )
  INTO v_bsr_stocks, v_bsr_broker_rows, v_bsr_stocks_with_min
  FROM public.tw_bsr_daily d
  WHERE d.trade_date = _trade_date;

  -- ---- Lane B/C/D: Institutional coverage ----
  SELECT count(DISTINCT i.stock_id) INTO v_inst_stocks
  FROM public.tw_institutional_daily i WHERE i.trade_date = _trade_date;

  SELECT count(DISTINCT i.stock_id) INTO v_inst_twse
  FROM public.tw_institutional_daily i WHERE i.trade_date = _trade_date AND i.source = 'twse_bfi82u';

  SELECT count(DISTINCT i.stock_id) INTO v_inst_tpex
  FROM public.tw_institutional_daily i WHERE i.trade_date = _trade_date AND i.source = 'tpex_bulk';

  SELECT count(DISTINCT i.stock_id) INTO v_inst_t86
  FROM public.tw_institutional_daily i WHERE i.trade_date = _trade_date AND i.source = 't86';

  IF v_bsr_stocks_with_min >= v_bsr_min_stocks THEN
    v_lane_a := 'sealed';
  ELSIF v_bsr_stocks_with_min > 0 THEN
    v_lane_a := 'partial';
  ELSE
    v_lane_a := 'pending';
  END IF;

  IF v_inst_stocks >= v_inst_min_stocks THEN
    v_lane_b := CASE WHEN v_inst_twse > 0 OR v_inst_stocks > 0 THEN 'sealed' ELSE 'partial' END;
    v_lane_c := CASE WHEN v_inst_tpex > 0 OR v_inst_stocks > 0 THEN 'sealed' ELSE 'partial' END;
  ELSIF v_inst_stocks > 0 THEN
    v_lane_b := 'partial';
    v_lane_c := 'partial';
  END IF;

  IF v_lane_a = 'sealed' AND v_lane_b = 'sealed' AND v_lane_c = 'sealed' THEN
    v_sealed_at := now();
    v_sealed_by_lane := 'ALL';
  ELSIF v_lane_a = 'sealed' AND v_lane_b <> 'sealed' THEN
    v_sealed_by_lane := 'A_ONLY';
    v_notes := 'BSR sealed, institutional coverage insufficient';
  ELSIF v_lane_a <> 'sealed' AND v_lane_b = 'sealed' THEN
    v_sealed_by_lane := 'BC_ONLY';
    v_notes := 'Institutional sealed, BSR coverage insufficient';
  END IF;

  INSERT INTO public.tw_bsr_daily_snapshot_status AS s (
    trade_date, status,
    lane_a_status, lane_b_status, lane_c_status,
    sealed_at, sealed_by_lane,
    coverage_stocks, coverage_brokers,
    updated_at
  ) VALUES (
    _trade_date,
    CASE WHEN v_sealed_at IS NOT NULL THEN 'ready' ELSE 'partial' END,
    v_lane_a, v_lane_b, v_lane_c,
    v_sealed_at, v_sealed_by_lane,
    v_bsr_stocks_with_min, v_bsr_broker_rows,
    now()
  )
  ON CONFLICT (trade_date) DO UPDATE SET
    lane_a_status = EXCLUDED.lane_a_status,
    lane_b_status = EXCLUDED.lane_b_status,
    lane_c_status = EXCLUDED.lane_c_status,
    sealed_at = COALESCE(s.sealed_at, EXCLUDED.sealed_at),
    sealed_by_lane = COALESCE(s.sealed_by_lane, EXCLUDED.sealed_by_lane),
    coverage_stocks = GREATEST(s.coverage_stocks, EXCLUDED.coverage_stocks),
    coverage_brokers = GREATEST(s.coverage_brokers, EXCLUDED.coverage_brokers),
    status = CASE
      WHEN s.sealed_at IS NOT NULL THEN 'ready'
      WHEN EXCLUDED.sealed_at IS NOT NULL THEN 'ready'
      ELSE EXCLUDED.status
    END,
    updated_at = now();

  RETURN QUERY SELECT
    _trade_date,
    v_lane_a, v_lane_b, v_lane_c,
    v_sealed_at, v_sealed_by_lane,
    v_bsr_stocks_with_min, v_bsr_broker_rows,
    v_bsr_stocks, v_inst_stocks,
    v_notes;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.record_bsr_api_call(_api text DEFAULT 'finmind'::text, _success boolean DEFAULT true, _rate_limited boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  _bucket timestamptz := date_trunc('minute', now());
BEGIN
  INSERT INTO public.tw_bsr_api_usage (bucket_start, api_name, call_count, success_count, error_count, rate_limited_count)
  VALUES (
    _bucket, _api, 1,
    CASE WHEN _success THEN 1 ELSE 0 END,
    CASE WHEN _success THEN 0 ELSE 1 END,
    CASE WHEN _rate_limited THEN 1 ELSE 0 END
  )
  ON CONFLICT (bucket_start, api_name) DO UPDATE SET
    call_count = tw_bsr_api_usage.call_count + 1,
    success_count = tw_bsr_api_usage.success_count + CASE WHEN _success THEN 1 ELSE 0 END,
    error_count = tw_bsr_api_usage.error_count + CASE WHEN _success THEN 0 ELSE 1 END,
    rate_limited_count = tw_bsr_api_usage.rate_limited_count + CASE WHEN _rate_limited THEN 1 ELSE 0 END;
END; $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.recover_quota_failed_bsr_jobs(p_max integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t0 timestamptz := clock_timestamp();
  v_invocation uuid := gen_random_uuid();
  v_cap int := LEAST(1, GREATEST(0, COALESCE(p_max, 0)));
  v_lock boolean;
  v_before jsonb;
  v_after jsonb;
  v_budget jsonb;
  v_breason text;
  v_pools jsonb;
  v_next_admission text;
  v_today_tw date := (now() AT TIME ZONE 'Asia/Taipei')::date;
  v_reconciled_id bigint;
  v_reconciled int := 0;
  v_token_id bigint;
  v_tokens int := 0;
  v_inspected int := 0;
  v_result jsonb;
  CANDIDATE_LIMIT constant int := 200;
  LOCK_KEY constant bigint := 771001;
BEGIN
  SELECT pg_try_advisory_xact_lock(LOCK_KEY) INTO v_lock;

  IF v_lock IS NOT TRUE THEN
    INSERT INTO public.data_source_refresh_logs
      (source_key, triggered_by, status, started_at, finished_at, duration_ms, row_count, metadata)
    VALUES ('bsr_quota_recovery', NULL, 'skipped', v_t0, clock_timestamp(),
            (EXTRACT(epoch FROM (clock_timestamp() - v_t0)) * 1000)::int, 0,
            jsonb_build_object('invocation_id', v_invocation, 'budget_reason', 'lock_contended',
                               'counting_mode', 'exact', 'tokens_issued', 0, 'reconciled', 0));
    RETURN jsonb_build_object('invocation_id', v_invocation, 'tokens_issued', 0, 'reconciled', 0,
                              'recovered', 0, 'budget_reason', 'lock_contended', 'counting_mode', 'exact');
  END IF;

  v_budget := public.bsr_recovery_budget(GREATEST(v_cap, 0));
  v_breason := v_budget->>'budget_reason';
  v_pools := v_budget->'pools';
  v_next_admission := v_budget->>'next_admission_at';
  v_before := v_budget->'metrics';
  v_cap := LEAST(v_cap, COALESCE((v_budget->>'budget')::int, 0));

  WITH pick AS (
    SELECT q.id
      FROM public.tw_bsr_sync_queue q
     WHERE q.status = 'failed'
       AND (q.last_error LIKE 'finmind_admission_%' OR q.last_error = 'quota_deferred')
       AND EXISTS (SELECT 1 FROM public.tw_chip_fact f
                    WHERE f.stock_id = q.stock_id AND f.trade_date = q.trade_date)
     ORDER BY q.trade_date DESC, q.enqueued_at ASC
     FOR UPDATE SKIP LOCKED
     LIMIT 1
  )
  UPDATE public.tw_bsr_sync_queue q
     SET status = 'done',
         last_error = 'reconciled_fact_exists',
         finished_at = now(),
         last_success_at = COALESCE(q.last_success_at, now()),
         updated_at = now()
    FROM pick
   WHERE q.id = pick.id
  RETURNING q.id INTO v_reconciled_id;

  IF v_reconciled_id IS NOT NULL THEN v_reconciled := 1; END IF;

  IF v_cap > 0 THEN
    WITH cand AS (
      SELECT q.id, q.stock_id, q.trade_date, q.priority, q.enqueued_at
        FROM public.tw_bsr_sync_queue q
       WHERE q.status = 'failed'
         AND (q.last_error LIKE 'finmind_admission_%' OR q.last_error = 'quota_deferred')
         AND q.max_attempts < 8
         AND NOT EXISTS (SELECT 1 FROM public.tw_chip_fact f
                          WHERE f.stock_id = q.stock_id AND f.trade_date = q.trade_date)
       ORDER BY q.trade_date DESC, q.enqueued_at ASC
       LIMIT CANDIDATE_LIMIT
    ),
    ready5 AS (
      SELECT s.stock_id, x.have5
        FROM (SELECT DISTINCT stock_id FROM cand) s
        CROSS JOIN LATERAL (
          SELECT count(DISTINCT f.trade_date) AS have5
            FROM public.tw_chip_fact f
           WHERE f.stock_id = s.stock_id AND f.trade_date >= v_today_tw - 10
        ) x
    ),
    actionable AS (
      SELECT c.id, c.trade_date, c.enqueued_at,
             CASE WHEN c.priority <= 1 THEN 'interactive'
                  WHEN c.priority = 2 THEN 'keepwarm'
                  ELSE 'backfill' END AS pool
        FROM cand c
        LEFT JOIN ready5 r ON r.stock_id = c.stock_id
       WHERE c.trade_date = public.expected_latest_bsr_date()
          OR (c.trade_date >= v_today_tw - 10 AND COALESCE(r.have5, 0) < 5)
    ),
    eligible AS (
      SELECT a.id
        FROM actionable a
        JOIN jsonb_array_elements(COALESCE(v_pools, '[]'::jsonb)) p
          ON p->>'pool' = a.pool AND (p->>'issue_ok')::boolean
       ORDER BY a.trade_date DESC, a.enqueued_at ASC
       LIMIT v_cap
    ),
    locked AS (
      SELECT q.id FROM public.tw_bsr_sync_queue q
       WHERE q.id IN (SELECT id FROM eligible)
       FOR UPDATE SKIP LOCKED
    )
    UPDATE public.tw_bsr_sync_queue q
       SET status = 'pending',
           max_attempts = q.max_attempts + 1,
           next_run_at = now(),
           started_at = NULL,
           finished_at = NULL,
           last_error = 'quota_recovery_token',
           updated_at = now()
      FROM locked
     WHERE q.id = locked.id
    RETURNING q.id INTO v_token_id;

    IF v_token_id IS NOT NULL THEN v_tokens := 1; END IF;

    SELECT LEAST(count(*), CANDIDATE_LIMIT) INTO v_inspected
      FROM public.tw_bsr_sync_queue q
     WHERE q.status = 'failed'
       AND (q.last_error LIKE 'finmind_admission_%' OR q.last_error = 'quota_deferred');
  END IF;

  v_after := public.bsr_backlog_metrics();

  INSERT INTO public.data_source_refresh_logs
    (source_key, triggered_by, status, started_at, finished_at, duration_ms, row_count, metadata)
  VALUES ('bsr_quota_recovery', NULL,
          CASE WHEN v_tokens > 0 OR v_reconciled > 0 THEN 'success' ELSE 'skipped' END,
          v_t0, clock_timestamp(),
          (EXTRACT(epoch FROM (clock_timestamp() - v_t0)) * 1000)::int,
          v_tokens,
          jsonb_build_object(
            'invocation_id', v_invocation,
            'budget_reason', v_breason,
            'degrade', v_budget->'degrade',
            'pools', v_pools,
            'pool_excluded', jsonb_build_array('interactive'),
            'counting_mode', 'exact',
            'candidates_inspected', v_inspected,
            'cap', v_cap,
            'tokens_issued', v_tokens,
            'reconciled', v_reconciled,
            'tokened_job_ids', CASE WHEN v_token_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_token_id) END,
            'reconciled_job_ids', CASE WHEN v_reconciled_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_reconciled_id) END,
            'metrics_before', v_before,
            'metrics_after', v_after,
            'next_admission_at', v_next_admission,
            'total_ms', (EXTRACT(epoch FROM (clock_timestamp() - v_t0)) * 1000)::int
          ));

  v_result := jsonb_build_object(
    'invocation_id', v_invocation,
    'tokens_issued', v_tokens,
    'reconciled', v_reconciled,
    'budget_reason', v_breason,
    'counting_mode', 'exact',
    'cap', v_cap,
    'candidates_inspected', v_inspected,
    'tokened_job_ids', CASE WHEN v_token_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_token_id) END,
    'reconciled_job_ids', CASE WHEN v_reconciled_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_reconciled_id) END,
    'next_admission_at', v_next_admission,
    'metrics_after', v_after
  );

  RETURN v_result || jsonb_build_object(
    'recovered', v_tokens,
    'remaining', COALESCE((v_after#>>'{cohort,legacy_quota_failed_total}')::int, 0)
  );
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.recover_stale_backfill_jobs(_stale_after interval DEFAULT '00:15:00'::interval)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  recovered_count INTEGER := 0;
  now_ts TIMESTAMPTZ := now();
BEGIN
  IF _stale_after < interval '0 seconds' THEN
    RAISE EXCEPTION '_stale_after must be non-negative';
  END IF;

  UPDATE public.backfill_job_queue
  SET status = 'pending',
      last_error = 'STALE_RUNNING_RECOVERED',
      next_run_at = now_ts,
      updated_at = now_ts
  WHERE status = 'running'
    AND updated_at < now_ts - _stale_after;

  GET DIAGNOSTICS recovered_count = ROW_COUNT;
  RETURN recovered_count;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.recover_stale_bsr_queue_jobs(p_stale_minutes integer DEFAULT 30, p_max_attempts integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_running int := 0; v_retry int := 0;
BEGIN
  WITH r AS (
    UPDATE public.tw_bsr_sync_queue q
       SET status = 'pending', next_run_at = now()
     WHERE q.status = 'running'
       AND q.started_at IS NOT NULL
       AND q.started_at < now() - make_interval(mins => p_stale_minutes)
    RETURNING 1
  ) SELECT count(*) INTO v_running FROM r;

  WITH f AS (
    UPDATE public.tw_bsr_sync_queue q
       SET status = 'pending',
           next_run_at = now() + make_interval(mins => LEAST(60, GREATEST(1, q.attempts) * 5))
     WHERE q.status IN ('failed','skipped')
       AND q.attempts < LEAST(q.max_attempts, p_max_attempts)
       AND EXISTS (
         SELECT 1 FROM public.checkup_prefetch_universe() u
          WHERE u.code = q.stock_id AND u.supported
       )
    RETURNING 1
  ) SELECT count(*) INTO v_retry FROM f;

  RETURN jsonb_build_object('running_reset', v_running, 'retry_requeued', v_retry);
END; $function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.refresh_bsr_coverage_daily(days integer DEFAULT 10)
 RETURNS TABLE(rows_upserted integer, date_from date, date_to date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from date := (current_date - GREATEST(days, 1))::date;
  v_to   date := current_date;
  v_count integer := 0;
BEGIN
  WITH bsr AS (
    SELECT
      stock_id,
      trade_date,
      COUNT(*)::int AS broker_count,
      COALESCE(SUM(buy_shares), 0)::bigint AS broker_sum_shares
    FROM public.tw_bsr_daily
    WHERE trade_date >= v_from
    GROUP BY stock_id, trade_date
  ),
  joined AS (
    SELECT
      b.stock_id,
      b.trade_date,
      b.broker_count,
      b.broker_sum_shares,
      s.volume_shares AS snapshot_volume_shares,
      CASE
        WHEN s.volume_shares IS NULL OR s.volume_shares = 0 THEN NULL
        ELSE ROUND((b.broker_sum_shares::numeric / s.volume_shares::numeric) * 100, 2)
      END AS coverage_pct
    FROM bsr b
    LEFT JOIN public.daily_price_snapshots s
      ON s.symbol = b.stock_id AND s.trade_date = b.trade_date
  ),
  classified AS (
    SELECT
      j.*,
      CASE
        WHEN snapshot_volume_shares IS NULL THEN 'missing_snapshot'
        WHEN coverage_pct IS NULL THEN 'missing_snapshot'
        WHEN coverage_pct > 120 THEN 'broker_over_cover'
        WHEN coverage_pct < 60 THEN 'broker_under_cover'
        ELSE 'ok'
      END AS coverage_class
    FROM joined j
  ),
  upserted AS (
    INSERT INTO public.bsr_coverage_daily AS t
      (stock_id, trade_date, broker_count, broker_sum_shares, snapshot_volume_shares, coverage_pct, coverage_class, computed_at)
    SELECT stock_id, trade_date, broker_count, broker_sum_shares, snapshot_volume_shares, coverage_pct, coverage_class, now()
    FROM classified
    ON CONFLICT (stock_id, trade_date) DO UPDATE
      SET broker_count = EXCLUDED.broker_count,
          broker_sum_shares = EXCLUDED.broker_sum_shares,
          snapshot_volume_shares = EXCLUDED.snapshot_volume_shares,
          coverage_pct = EXCLUDED.coverage_pct,
          coverage_class = EXCLUDED.coverage_class,
          computed_at = now()
    RETURNING 1
  )
  SELECT COUNT(*)::int INTO v_count FROM upserted;

  RETURN QUERY SELECT v_count, v_from, v_to;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.release_bsr_reservation(_reservation_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.tw_bsr_api_reservations
     SET released = true, settled_at = now()
   WHERE id = _reservation_id
     AND settled_at IS NULL
     AND released = false;
END;
