DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.reserve_bsr_api_quota(_limit integer, _api text, _lease_seconds integer, _correlation_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(granted boolean, reservation_id bigint, used integer, remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _window_start timestamptz := now() - interval '1 hour';
  _used integer;
  _in_flight integer;
  _total integer;
  _new_id bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('bsr_reserve_' || _api));

  UPDATE public.tw_bsr_api_reservations
     SET released = true, settled_at = now()
   WHERE api_name = _api AND settled_at IS NULL AND released = false AND expires_at < now();

  SELECT COALESCE(SUM(call_count), 0) INTO _used
    FROM public.tw_bsr_api_usage
   WHERE api_name = _api AND bucket_start >= _window_start;

  SELECT COUNT(*) INTO _in_flight
    FROM public.tw_bsr_api_reservations
   WHERE api_name = _api AND settled_at IS NULL AND released = false;

  _total := _used + _in_flight;

  IF _total >= _limit THEN
    RETURN QUERY SELECT false, NULL::bigint, _total, GREATEST(0, _limit - _total);
    RETURN;
  END IF;

  INSERT INTO public.tw_bsr_api_reservations(api_name, reserved_at, expires_at, correlation_id)
  VALUES (_api, now(), now() + make_interval(secs => GREATEST(1, _lease_seconds)), _correlation_id)
  RETURNING id INTO _new_id;

  RETURN QUERY SELECT true, _new_id, _total + 1, GREATEST(0, _limit - (_total + 1));
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.reserve_bsr_api_quota(_limit integer, _api text, _lease_seconds integer, _correlation_id uuid DEFAULT NULL::uuid, _tier smallint DEFAULT NULL::smallint)
 RETURNS TABLE(granted boolean, reservation_id bigint, used integer, remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_used integer;
  v_since timestamptz := now() - interval '1 hour';
  v_new_id bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('bsr_quota:' || _api, 0));

  SELECT COUNT(*) INTO v_used
    FROM public.tw_bsr_api_reservations
   WHERE api_name = _api
     AND reserved_at >= v_since
     AND released = false
     AND (settled_at IS NOT NULL OR expires_at > now());

  IF v_used >= _limit THEN
    RETURN QUERY SELECT false, NULL::bigint, v_used, GREATEST(0, _limit - v_used);
    RETURN;
  END IF;

  INSERT INTO public.tw_bsr_api_reservations
    (api_name, reserved_at, expires_at, correlation_id, tier)
  VALUES
    (_api, now(), now() + make_interval(secs => _lease_seconds), _correlation_id, _tier)
  RETURNING id INTO v_new_id;

  RETURN QUERY SELECT true, v_new_id, v_used + 1, GREATEST(0, _limit - v_used - 1);
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.reset_data_source_circuit(_source text)
 RETURNS data_source_health
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result public.data_source_health;
BEGIN
  IF NOT public.has_role(auth.uid(), 'company_admin') THEN
    RAISE EXCEPTION 'forbidden: company_admin required';
  END IF;

  UPDATE public.data_source_health
     SET circuit_state = 'closed',
         consecutive_failures = 0,
         fail_count_10m = 0,
         ok_count_10m = 0,
         disabled_until = NULL,
         updated_at = now()
   WHERE source = _source
  RETURNING * INTO result;

  IF NOT FOUND THEN
    INSERT INTO public.data_source_health (source, circuit_state, updated_at)
    VALUES (_source, 'closed', now())
    RETURNING * INTO result;
  END IF;

  RETURN result;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.run_rls_subscription_tests()
 RETURNS TABLE(test_name text, passed boolean, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := '2026-07-14 12:00:00+08'::timestamptz;
  v_user uuid := '00000000-0000-0000-0000-0000000000aa'::uuid;
  v_user_gap uuid := '00000000-0000-0000-0000-0000000000bb'::uuid;
  v_user_expired uuid := '00000000-0000-0000-0000-0000000000cc'::uuid;
  v_expert_mentor uuid;
  v_expert_advisor uuid;
  v_plan_m uuid;
  v_plan_a uuid;
  v_seen boolean;
BEGIN
  -- === Part A：純視窗函數單元測試 ===
  test_name := 'mentor: signal within window'; detail := '';
  passed := public.signal_in_subscription_window('mentor'::expert_role,
    '2026-06-01'::timestamptz, '2026-07-01'::timestamptz, '2026-06-15'::timestamptz);
  RETURN NEXT;

  test_name := 'mentor: 7-day lookback within 7d before start → visible';
  passed := public.signal_in_subscription_window('mentor'::expert_role,
    '2026-06-08'::timestamptz, '2026-07-08'::timestamptz, '2026-06-02'::timestamptz);
  RETURN NEXT;

  test_name := 'mentor: 7-day lookback boundary (exactly 7d) → visible';
  passed := public.signal_in_subscription_window('mentor'::expert_role,
    '2026-06-08 12:00+08'::timestamptz, '2026-07-08'::timestamptz, '2026-06-01 12:00+08'::timestamptz);
  RETURN NEXT;

  test_name := 'mentor: 8d before start → NOT visible';
  passed := NOT public.signal_in_subscription_window('mentor'::expert_role,
    '2026-06-08 12:00+08'::timestamptz, '2026-07-08'::timestamptz, '2026-05-31 11:00+08'::timestamptz);
  RETURN NEXT;

  test_name := 'mentor: signal after expires_at → NOT visible';
  passed := NOT public.signal_in_subscription_window('mentor'::expert_role,
    '2026-06-01'::timestamptz, '2026-07-01'::timestamptz, '2026-07-05'::timestamptz);
  RETURN NEXT;

  test_name := 'advisor: 7-day lookback does NOT apply (1d before start → NOT visible)';
  passed := NOT public.signal_in_subscription_window('advisor'::expert_role,
    '2026-06-08'::timestamptz, '2026-07-08'::timestamptz, '2026-06-07'::timestamptz);
  RETURN NEXT;

  test_name := 'advisor: signal exactly at started_at → visible';
  passed := public.signal_in_subscription_window('advisor'::expert_role,
    '2026-06-08 12:00+08'::timestamptz, '2026-07-08'::timestamptz, '2026-06-08 12:00+08'::timestamptz);
  RETURN NEXT;

  test_name := 'mentor: no expires_at (unlimited) → future signal visible';
  passed := public.signal_in_subscription_window('mentor'::expert_role,
    '2026-06-01'::timestamptz, NULL, '2030-01-01'::timestamptz);
  RETURN NEXT;

  -- === Part B：端到端 has_active_subscription_after 測試（seed 後 rollback）===
  BEGIN
    INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, created_at, updated_at)
    VALUES
      (v_user,         '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rls-test-a@test.local', '', v_now, v_now),
      (v_user_gap,     '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rls-test-b@test.local', '', v_now, v_now),
      (v_user_expired, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rls-test-c@test.local', '', v_now, v_now)
    ON CONFLICT (id) DO NOTHING;

    INSERT INTO public.experts (user_id, slug, name, role)
    VALUES (v_user, 'rls-test-mentor-'  || substr(md5(random()::text),1,8), 'RLS Test Mentor',  'mentor')
    RETURNING id INTO v_expert_mentor;

    INSERT INTO public.experts (user_id, slug, name, role)
    VALUES (v_user, 'rls-test-advisor-' || substr(md5(random()::text),1,8), 'RLS Test Advisor', 'advisor')
    RETURNING id INTO v_expert_advisor;

    INSERT INTO public.expert_plans (expert_id, name, plan_type, price_monthly, is_active, review_status)
    VALUES (v_expert_mentor,  'M', 'mentor_weekly_journal'::plan_type, 100, true, 'approved'::plan_review_status)
    RETURNING id INTO v_plan_m;

    INSERT INTO public.expert_plans (expert_id, name, plan_type, price_monthly, is_active, review_status)
    VALUES (v_expert_advisor, 'A', 'analyst_signal_l1'::plan_type, 100, true, 'approved'::plan_review_status)
    RETURNING id INTO v_plan_a;

    INSERT INTO public.member_subscriptions (user_id, plan_id, status, started_at, expires_at)
    VALUES
      (v_user, v_plan_m, 'expired', '2026-05-10'::timestamptz, '2026-06-10'::timestamptz),
      (v_user, v_plan_m, 'active',  '2026-07-14'::timestamptz, '2026-08-14'::timestamptz);

    INSERT INTO public.member_subscriptions (user_id, plan_id, status, started_at, expires_at)
    VALUES (v_user_gap, v_plan_m, 'active', '2026-07-14'::timestamptz, '2026-08-14'::timestamptz);

    INSERT INTO public.member_subscriptions (user_id, plan_id, status, started_at, expires_at)
    VALUES (v_user_expired, v_plan_m, 'expired', '2026-05-10'::timestamptz, '2026-06-10'::timestamptz);

    SELECT EXISTS(SELECT 1 FROM public.has_active_subscription_after(v_user, '2026-05-20'::timestamptz)
      WHERE expert_id = v_expert_mentor) INTO v_seen;
    test_name := 'renew after expire: old-window signal is unlocked';
    passed := v_seen; detail := CASE WHEN v_seen THEN '' ELSE 'expected visible after renewal' END;
    RETURN NEXT;

    SELECT EXISTS(SELECT 1 FROM public.has_active_subscription_after(v_user, '2026-06-20'::timestamptz)
      WHERE expert_id = v_expert_mentor) INTO v_seen;
    test_name := 'gap window: signal published in gap → NOT visible';
    passed := NOT v_seen; detail := CASE WHEN v_seen THEN 'gap signal must NOT be visible' ELSE '' END;
    RETURN NEXT;

    SELECT EXISTS(SELECT 1 FROM public.has_active_subscription_after(v_user_gap, '2026-05-20'::timestamptz)
      WHERE expert_id = v_expert_mentor) INTO v_seen;
    test_name := 'no prior subscription: pre-active signal → NOT visible';
    passed := NOT v_seen; detail := CASE WHEN v_seen THEN 'must not see history user never paid for' ELSE '' END;
    RETURN NEXT;

    SELECT EXISTS(SELECT 1 FROM public.has_active_subscription_after(v_user_gap, '2026-07-08'::timestamptz)
      WHERE expert_id = v_expert_mentor) INTO v_seen;
    test_name := 'mentor 7d lookback: 6 days before start → visible';
    passed := v_seen; detail := CASE WHEN v_seen THEN '' ELSE '7d lookback broken' END;
    RETURN NEXT;

    SELECT EXISTS(SELECT 1 FROM public.has_active_subscription_after(v_user_gap, '2026-07-06 11:00+08'::timestamptz)
      WHERE expert_id = v_expert_mentor) INTO v_seen;
    test_name := 'mentor 7d lookback: 8 days before start → NOT visible';
    passed := NOT v_seen; detail := CASE WHEN v_seen THEN '7d boundary leaks' ELSE '' END;
    RETURN NEXT;

    SELECT EXISTS(SELECT 1 FROM public.has_active_subscription_after(v_user_expired, '2026-05-20'::timestamptz)
      WHERE expert_id = v_expert_mentor) INTO v_seen;
    test_name := 'expired only (no active): historical signal → NOT visible';
    passed := NOT v_seen; detail := CASE WHEN v_seen THEN 'expired user must not read history' ELSE '' END;
    RETURN NEXT;

    INSERT INTO public.member_subscriptions (user_id, plan_id, status, started_at, expires_at)
    VALUES (v_user_gap, v_plan_a, 'active', '2026-07-14'::timestamptz, '2026-08-14'::timestamptz);

    SELECT EXISTS(SELECT 1 FROM public.has_active_subscription_after(v_user_gap, '2026-07-10'::timestamptz)
      WHERE expert_id = v_expert_advisor) INTO v_seen;
    test_name := 'advisor: no 7d lookback (4 days before start) → NOT visible';
    passed := NOT v_seen; detail := CASE WHEN v_seen THEN 'advisor should not have 7d lookback' ELSE '' END;
    RETURN NEXT;

    RAISE EXCEPTION 'ROLLBACK_TESTS';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM <> 'ROLLBACK_TESTS' THEN
      test_name := 'seed/execution error'; passed := false; detail := SQLERRM;
      RETURN NEXT;
    END IF;
  END;

  RETURN;
END;
$function$
$__f$; EXCEPTION WHEN others THEN RAISE NOTICE 'fn skipped: %', SQLERRM; END $__r$;
DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.save_signal_batch(_expert_id uuid, _batch_id uuid, _signals jsonb, _legs jsonb DEFAULT '[]'::jsonb, _is_editing boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller uuid := auth.uid();
  _inserted integer := 0;
  _old_ids uuid[];
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_role(_caller, 'company_admin'::app_role)
    OR EXISTS (SELECT 1 FROM public.experts e WHERE e.id = _expert_id AND e.user_id = _caller)
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF _signals IS NULL OR jsonb_typeof(_signals) <> 'array' OR jsonb_array_length(_signals) = 0 THEN
    RAISE EXCEPTION 'empty_signals' USING ERRCODE = '22023';
  END IF;

  -- 所有 row 必須屬於同一位分析師與同一批次
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_signals) s
    WHERE (s->>'expert_id')::uuid IS DISTINCT FROM _expert_id
       OR (s->>'batch_id')::uuid IS DISTINCT FROM _batch_id
  ) THEN
    RAISE EXCEPTION 'batch_mismatch' USING ERRCODE = '22023';
  END IF;

  IF _is_editing THEN
    SELECT array_agg(id) INTO _old_ids
    FROM public.expert_signals
    WHERE batch_id = _batch_id AND expert_id = _expert_id;

    IF _old_ids IS NOT NULL AND array_length(_old_ids, 1) > 0 THEN
      DELETE FROM public.trade_records WHERE signal_id = ANY(_old_ids);
      DELETE FROM public.expert_signal_legs WHERE signal_id = ANY(_old_ids);
      DELETE FROM public.expert_signals WHERE id = ANY(_old_ids);
    END IF;
  END IF;

  WITH src AS (
    SELECT * FROM jsonb_populate_recordset(null::public.expert_signals, _signals)
  )
  INSERT INTO public.expert_signals (
    id, expert_id, plan_id, batch_id, instrument, action, price_hint,
    reason_summary, reason_detail, risk_notes, learning_points,
    status, published_at, created_at, quantity, quantity_unit,
    teaching_topic, overall_summary, executed_at,
    is_combo, combo_strategy, net_premium, max_loss_per_unit, max_profit_per_unit
  )
  SELECT
    COALESCE(src.id, gen_random_uuid()), _expert_id, src.plan_id, _batch_id, src.instrument,
    src.action, src.price_hint, src.reason_summary, src.reason_detail, src.risk_notes,
    src.learning_points, COALESCE(src.status, 'published'::signal_status),
    COALESCE(src.published_at, now()), COALESCE(src.created_at, now()),
    src.quantity, src.quantity_unit, src.teaching_topic, src.overall_summary,
    src.executed_at, COALESCE(src.is_combo, false), src.combo_strategy,
    src.net_premium, src.max_loss_per_unit, src.max_profit_per_unit
  FROM src;

  GET DIAGNOSTICS _inserted = ROW_COUNT;

  IF _legs IS NOT NULL AND jsonb_typeof(_legs) = 'array' AND jsonb_array_length(_legs) > 0 THEN
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(_legs) l
      WHERE NOT EXISTS (
        SELECT 1 FROM public.expert_signals es
        WHERE es.id = (l->>'signal_id')::uuid AND es.batch_id = _batch_id
      )
    ) THEN
      RAISE EXCEPTION 'leg_signal_mismatch' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.expert_signal_legs (
      signal_id, leg_index, occ_symbol, underlying, expiry, right_type,
      strike, side, ratio, leg_price
    )
    SELECT signal_id, leg_index, occ_symbol, underlying, expiry, right_type,
           strike, side, ratio, leg_price
    FROM jsonb_populate_recordset(null::public.expert_signal_legs, _legs);
  END IF;

  RETURN _inserted;
END;
$function$
