DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.signal_in_subscription_window(_role expert_role, _started_at timestamp with time zone, _expires_at timestamp with time zone, _published_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _role = 'mentor' THEN
      (_published_at + INTERVAL '7 days') >= _started_at
      AND (_expires_at IS NULL OR _published_at <= _expires_at)
    ELSE
      _published_at >= _started_at
      AND (_expires_at IS NULL OR _published_at <= _expires_at)
  END
