DO $__r$ BEGIN EXECUTE $__f$CREATE OR REPLACE FUNCTION public.tw_bsr_sync_config_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.tw_bsr_sync_config_history (key, version, config, changed_by, note)
    VALUES (NEW.key, NEW.version, NEW.config, NEW.updated_by, NEW.note);
    RETURN NEW;
  END IF;

  IF NEW.config IS DISTINCT FROM OLD.config THEN
    NEW.version := OLD.version + 1;
    NEW.updated_at := now();
    INSERT INTO public.tw_bsr_sync_config_history (key, version, config, changed_by, note)
    VALUES (NEW.key, NEW.version, NEW.config, NEW.updated_by, NEW.note);
  END IF;
  RETURN NEW;
END;
$function$
